INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('claim', 'claim:c1', 'c1', 'Safety-Led Operations', '{"canonical_wording":"Volcano travel is unpredictable, so JVTO focuses on operational certainty: disciplined decisions, clear safety boundaries, and realistic expectations.","name":"Safety-Led Operations","domain":"credentials","category":"trust-signal","last_verified":"2026-05-26","evidence_count":5}'::jsonb, '{"canonical_wording":"llm-wiki-trust","name":"llm-wiki-trust","domain":"llm-wiki-trust","category":"llm-wiki-trust","last_verified":"llm-wiki-trust","evidence_count":"llm-wiki-trust"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('claim', 'claim:c2', 'c2', 'Private Tours (Execution Control)', '{"canonical_wording":"JVTO runs private tours by default so timing, pacing, and safety decisions stay consistent for your group.","name":"Private Tours (Execution Control)","domain":"products","category":"tour-package","last_verified":"2026-05-12","evidence_count":1}'::jsonb, '{"canonical_wording":"llm-wiki-trust","name":"llm-wiki-trust","domain":"llm-wiki-trust","category":"llm-wiki-trust","last_verified":"llm-wiki-trust","evidence_count":"llm-wiki-trust"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
