INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('claim', 'claim:c4', 'c4', 'Ijen Health-Screening Coordination', '{"canonical_wording":"On routes that include Mount Ijen, JVTO integrates health screening as a practical safety step, not a formality.","name":"Ijen Health-Screening Coordination","domain":"credentials","category":"medical-protocol","last_verified":"2026-05-26","evidence_count":3}'::jsonb, '{"canonical_wording":"llm-wiki-trust","name":"llm-wiki-trust","domain":"llm-wiki-trust","category":"llm-wiki-trust","last_verified":"llm-wiki-trust","evidence_count":"llm-wiki-trust"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('claim', 'claim:c5', 'c5', 'Proof-First Trust (Verification Layer)', '{"canonical_wording":"JVTO organizes trust signals as a verification layer: clear claims, context, and evidence links — not just marketing statements.","name":"Proof-First Trust (Verification Layer)","domain":"credentials","category":"trust-signal","last_verified":"2026-05-26","evidence_count":2}'::jsonb, '{"canonical_wording":"llm-wiki-trust","name":"llm-wiki-trust","domain":"llm-wiki-trust","category":"llm-wiki-trust","last_verified":"llm-wiki-trust","evidence_count":"llm-wiki-trust"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('claim', 'claim:c6', 'c6', 'Reviews Registry (Independent Validation)', '{"canonical_wording":"JVTO treats reviews as a registry: grouped by platform and theme, so guests can validate patterns instead of reading random quotes.","name":"Reviews Registry (Independent Validation)","domain":"reviews","category":"review-compilation","last_verified":"2026-05-18","evidence_count":2}'::jsonb, '{"canonical_wording":"llm-wiki-trust","name":"llm-wiki-trust","domain":"llm-wiki-trust","category":"llm-wiki-trust","last_verified":"llm-wiki-trust","evidence_count":"llm-wiki-trust"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('claim', 'claim:c7', 'c7', 'Our Team (Personality Economy + Operational Credibility)', '{"canonical_wording":"JVTO''s product is executed by real people. The Team Registry shows roles, routes, and proof from review mentions — not generic bios.","name":"Our Team (Personality Economy + Operational Credibility)","domain":"people","category":"crew-profile","last_verified":"2026-05-25","evidence_count":1}'::jsonb, '{"canonical_wording":"llm-wiki-trust","name":"llm-wiki-trust","domain":"llm-wiki-trust","category":"llm-wiki-trust","last_verified":"llm-wiki-trust","evidence_count":"llm-wiki-trust"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('claim', 'claim:c8', 'c8', 'Partners as Context (HPWKI / INDECON / ISIC)', '{"canonical_wording":"JVTO partnerships are explained by function: competence context (HPWKI), sustainability context (INDECON), and verification logic (ISIC).","name":"Partners as Context (HPWKI / INDECON / ISIC)","domain":"credentials","category":"trust-signal","last_verified":"2026-05-16","evidence_count":2}'::jsonb, '{"canonical_wording":"llm-wiki-trust","name":"llm-wiki-trust","domain":"llm-wiki-trust","category":"llm-wiki-trust","last_verified":"llm-wiki-trust","evidence_count":"llm-wiki-trust"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
