INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('destination', 'destination:kawah-ijen', 'kawah-ijen', 'Kawah Ijen (Ijen Crater)', '{"narrative":"Kawah Ijen is an active volcano at 2,386 m with the world''s highest-volume acidic crater lake. Famous for the pre-dawn blue fire sulfuric-gas phenomenon — visible only in suitable weather and gas conditions. Access from Paltuding trailhead via a steep ~3 km night hike. BBKSDA East Java is the regulatory authority.","name":"Kawah Ijen (Ijen Crater)","type":"Active stratovolcano","elevation_m":2386,"operational":{"elevation_m":2386,"difficulty_level":"Moderate","best_time_to_visit":"May–October (dry season). Begin trek at 01:00–02:00 AM for blue fire and sunrise.","jeep_required":false,"standard_tour_start_time":"00:00","entrance_ticket_domestic_idr":75000,"entrance_ticket_foreign_idr":150000,"required_gear":"Thermal layers, waterproof jacket, sturdy trekking boots, gas mask (for sulfur fumes), headlamp, warm hat."}}'::jsonb, '{"narrative":"llm-wiki-trust","name":"llm-wiki-trust","type":"llm-wiki-trust","elevation_m":"llm-wiki-trust","operational":"itinerary-core"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('destination', 'destination:madakaripura', 'madakaripura', 'Madakaripura Waterfall (Air Terjun Madakaripura)', '{"narrative":"Madakaripura is Java''s tallest waterfall in Probolinggo, East Java. A narrow canyon gorge leads to a horseshoe curtain waterfall fed from multiple directions. Historical context: said to be the final meditation site of Gajah Mada, Majapahit prime minister. Easy ~20 min trek from roadside parking.","name":"Madakaripura Waterfall (Air Terjun Madakaripura)","type":"Horseshoe curtain waterfall in narrow canyon","operational":{"elevation_m":620,"difficulty_level":"Moderate","best_time_to_visit":"May–October. Morning or early afternoon for best light.","jeep_required":false,"standard_tour_start_time":"08:00","entrance_ticket_domestic_idr":90000,"entrance_ticket_foreign_idr":90000,"required_gear":"Quick-dry clothing, waterproof bag, water shoes/sandals, poncho (expect to get fully wet), snacks."}}'::jsonb, '{"narrative":"llm-wiki-trust","name":"llm-wiki-trust","type":"llm-wiki-trust","operational":"itinerary-core"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('destination', 'destination:malang-city', 'malang-city', NULL, '{"operational":{"elevation_m":452,"difficulty_level":null,"best_time_to_visit":"Year-round; cooler and more pleasant April–October.","jeep_required":false,"entrance_ticket_domestic_idr":null,"entrance_ticket_foreign_idr":null,"required_gear":null}}'::jsonb, '{"operational":"itinerary-core"}'::jsonb, 'itinerary-core', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('destination', 'destination:mount-bromo', 'mount-bromo', 'Mount Bromo (Gunung Bromo)', '{"narrative":"Mount Bromo is an active volcano in the Tengger caldera, East Java. Best known for the Penanjakan sunrise viewpoint over the sea-of-sand caldera floor and the active smoking crater. Accessed by 4WD jeep from Cemoro Lawang in the pre-dawn window (03:00–05:00).","name":"Mount Bromo (Gunung Bromo)","type":"Active stratovolcano","elevation_m":2329,"operational":{"elevation_m":2329,"difficulty_level":"Easy to Moderate","best_time_to_visit":"May–October (dry season). Arrive at viewpoint by 04:30 AM for sunrise.","jeep_required":true,"standard_tour_start_time":"03:00","entrance_ticket_domestic_idr":160000,"entrance_ticket_foreign_idr":320000,"required_gear":"Thermal jacket, sturdy trekking boots, flashlight/headlamp, sunscreen, dust/surgical mask."}}'::jsonb, '{"narrative":"llm-wiki-trust","name":"llm-wiki-trust","type":"llm-wiki-trust","elevation_m":"llm-wiki-trust","operational":"itinerary-core"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('destination', 'destination:papuma-beach', 'papuma-beach', 'Papuma Beach (Pantai Papuma)', '{"narrative":"Papuma Beach in Jember offers white sand and dramatic coastal rock formations. JVTO includes it as a coastal contrast stop on Papuma-family packages (4D+). Best for guests who want a beach break on an otherwise volcano-focused East Java itinerary.","name":"Papuma Beach (Pantai Papuma)","type":"White-sand beach with rocky cape (Tanjung Papuma)","elevation_m":{"beach":0,"cape_headland":86},"operational":{"elevation_m":0,"difficulty_level":"Easy","best_time_to_visit":"May–October. Late afternoon for sunset views.","jeep_required":false,"standard_tour_start_time":"14:00","entrance_ticket_domestic_idr":44000,"entrance_ticket_foreign_idr":44000,"required_gear":"Light clothing, sandals, sunscreen, hat, water, camera."}}'::jsonb, '{"narrative":"llm-wiki-trust","name":"llm-wiki-trust","type":"llm-wiki-trust","elevation_m":"llm-wiki-trust","operational":"itinerary-core"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
