INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('destination', 'destination:tumpak-sewu', 'tumpak-sewu', 'Tumpak Sewu Waterfall (Air Terjun Tumpak Sewu)', '{"narrative":"Tumpak Sewu is a multi-tiered canyon waterfall (~120 m) in Lumajang, East Java. Nicknamed ''Java''s Niagara'' for its curtain of streams cascading over a curved cliff face into a canyon. Accessed via rim viewpoint or steep canyon descent (~300 steps).","name":"Tumpak Sewu Waterfall (Air Terjun Tumpak Sewu)","type":"Multi-tiered curtain waterfall","operational":{"elevation_m":400,"difficulty_level":"Moderate","best_time_to_visit":"May–October (dry season). Morning for best light and fewer crowds.","jeep_required":false,"standard_tour_start_time":"07:00","entrance_ticket_domestic_idr":100000,"entrance_ticket_foreign_idr":100000,"required_gear":"Quick-dry clothing, non-slip shoes/sandals, poncho, waterproof bag for valuables, trekking poles optional."}}'::jsonb, '{"narrative":"llm-wiki-trust","name":"llm-wiki-trust","type":"llm-wiki-trust","operational":"itinerary-core"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
