INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-anti-fraud', 'policy-anti-fraud', 'Booking Safety & Anti-Fraud', '{"category":"policy","scope":"global","title":"Booking Safety & Anti-Fraud","short_answer":"Use only JVTO''s official channels; JVTO never asks for full card numbers, CVV, banking passwords, or OTP codes.","detail_summary":"Book and pay only through JVTO''s official channels — the website, the official WhatsApp number, the official email, and JVTO''s listed payment links and accounts. JVTO never asks for your full card number, CVV, online banking password, or one-time codes by chat or email. If an account number, link, or contact looks different, pause and verify through an official channel.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-booking-paths', 'policy-booking-paths', 'How to Book', '{"category":"policy","scope":"global","title":"How to Book","short_answer":"JVTO accepts bookings only through the official website; WhatsApp and email are for support, not for booking.","detail_summary":"JVTO accepts bookings only through the official JVTO website. WhatsApp and email are for customer assistance only and do not create, confirm, modify, cancel, or transfer a booking.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-cancellation-package-credit', 'policy-cancellation-package-credit', 'Cancellation & Lifetime Package Credit', '{"category":"policy","scope":"global","title":"Cancellation & Lifetime Package Credit","short_answer":"A 48-hour cut-off: full cancellations 48h+ before Day 1 become Lifetime Package Credit; cash refunds apply only to partial passenger cancellations.","detail_summary":"Full cancellation 48h+ before Day 1 converts the confirmed package to Lifetime Package Credit (never expires; same package, pax, and price; one transfer; not cash). Within 48h it is forfeited. Partial passenger cancellations get a cash refund of the cancelled travelers'' price (100% at 48h+, 50% within 48h). Verified flight cancellations can reactivate the package for a 50% Recovery Fee.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-ijen-health-screening', 'policy-ijen-health-screening', 'Ijen Health Screening', '{"category":"policy","scope":"ijen_scoped","title":"Ijen Health Screening","short_answer":"For Ijen crater hikes, a health certificate is mandatory for every guest before crater entry — JVTO coordinates the screening with licensed medical staff.","detail_summary":"A health certificate is mandatory for every guest before crater access at Kawah Ijen; JVTO coordinates the screening with licensed medical staff and the verified certificate is checked at the crater gate. The East Java conservation authority (BBKSDA), Surat Edaran SE.1658/KSA.9/2024, is cited as the supporting authority.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-ijen-monthly-closure', 'policy-ijen-monthly-closure', 'Ijen Monthly Closure (Rijik Program)', '{"category":"policy","scope":"ijen_scoped","title":"Ijen Monthly Closure (Rijik Program)","short_answer":"Kawah Ijen closes to all visitors on the first Friday of each month for the Rijik ecosystem-cleaning program; JVTO schedules tours around it so guests are unaffected.","detail_summary":"Tourism Nature Park (TWA) Kawah Ijen closes completely to all tourism and mining activity on the **first Friday of every month** (00:00–23:59 WIB) for the **Rijik** ecosystem-cleaning program, which has run since March 2019.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-inclusions-exclusions', 'policy-inclusions-exclusions', 'What''s Included', '{"category":"policy","scope":"global","title":"What''s Included","short_answer":"JVTO tours are all-inclusive of transport, crew, entrance fees, water, and stated meals; flights, insurance, tips, and personal expenses are excluded.","detail_summary":"Every JVTO package includes private transport, a dedicated driver and guide(s), all entrance fees and permits, drinking water, full pick-up to drop-off assistance, and meals as stated (at least breakfast). Bromo tours add the private 4WD jeep; Ijen tours add gas masks and trekking poles (and mandatory health-screening coordination — a certificate is required for every guest before crater entry); Bali-origin tours add the ferry crossing.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-isic-student', 'policy-isic-student', 'ISIC Student Pricing', '{"category":"policy","scope":"conditional_eligible","title":"ISIC Student Pricing","short_answer":"JVTO is an official ISIC provider offering student pricing on selected packages to verified ISIC cardholders.","detail_summary":"JVTO is an official ISIC (International Student Identity Card) provider — provider ID 259268, listed publicly on the ISIC website. Verified ISIC cardholders can receive student pricing on selected packages.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-natural-phenomena', 'policy-natural-phenomena', 'Natural Phenomena Are Not Guaranteed', '{"category":"policy","scope":"global","title":"Natural Phenomena Are Not Guaranteed","short_answer":"JVTO cannot guarantee weather-dependent sights such as sunrise or Ijen''s blue fire; itineraries are planned to maximise the chance.","detail_summary":"Weather-dependent sights — a clear sunrise, or Ijen''s blue fire — cannot be guaranteed, because cloud, weather, and volcanic gas are outside any operator''s control. JVTO plans timing and routes to maximise the chance of good conditions, and may adjust timing or routing for safety.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-payment-deposit', 'policy-payment-deposit', 'Payment & Deposit', '{"category":"policy","scope":"global","title":"Payment & Deposit","short_answer":"A deposit secures the booking, with the balance due before the tour; exact amounts and deadlines are on the booking page.","detail_summary":"A deposit (standard 20% of the booking value) secures a booking, with the balance due before the tour starts; close-to-departure bookings may require fuller payment. Exact amounts, accepted methods, and deadlines are shown at checkout and on the booking information page.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('general_module', 'general_module:policy-police-escort', 'policy-police-escort', 'Police Escort for Large Groups', '{"category":"policy","scope":"conditional_large_group","title":"Police Escort for Large Groups","short_answer":"For large groups, JVTO can coordinate an official traffic-police escort on some road segments, subject to authority approval.","detail_summary":"For large groups (typically around 18 or more travelers), JVTO can coordinate an official traffic-police escort on certain road segments where the relevant Traffic Police unit approves it. This is a coordination service subject to authority approval, not a default inclusion. See the travel-guide page for how it works and any group incentives.","customer_visible":true,"reusable":true}'::jsonb, '{"category":"knowledge-catalog-okf","scope":"knowledge-catalog-okf","title":"knowledge-catalog-okf","short_answer":"knowledge-catalog-okf","detail_summary":"knowledge-catalog-okf","customer_visible":"knowledge-catalog-okf","reusable":"knowledge-catalog-okf"}'::jsonb, 'knowledge-catalog-okf', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
