INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('policy_document', 'policy_document:booking-paths', 'booking-paths', NULL, '{"domain":"Booking Paths","summary":"**Website-only booking.** JVTO accepts bookings exclusively through the official website checkout under a valid JVTO Booking ID. WhatsApp/email are support channels only — they never create, confirm, modify, cancel, or transfer a booking.","evidence_count":2,"canonical_sources":["products/packages-overview.md"]}'::jsonb, '{"domain":"llm-wiki-policy","summary":"llm-wiki-policy","evidence_count":"llm-wiki-policy","canonical_sources":"llm-wiki-policy"}'::jsonb, 'llm-wiki-policy', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('policy_document', 'policy_document:cancellation-package-credit', 'cancellation-package-credit', NULL, '{"domain":"Cancellation / Package Credit","summary":"**Canonical logic lives in the YAML** (compiler reads it directly). Full voluntary ≥48h → Lifetime Package Credit (no cash); full <48h → forfeited. **Partial passenger cancellation** (booking continues): ≥48h → 100% cash refund of cancelled pax price, <48h → 50%, after Day 1 → 0%. Package Credit: no expiry, no cash value, same package/pax/price locked, one transfer, no split. Flight disruption → 50% Recovery Fee (once).","evidence_count":3,"canonical_sources":["policies/cancellation-package-credit.yml"],"decision_matrix":{"schema_version":"cancellation-policy/v2.0","policy_version":"2026-07","effective_from":"2026-07-15","cutoff_hours":48,"cutoff_comparison":"inclusive","cutoff_based_on":"day_1_start_at","rules":{"full_voluntary_gte_48h":{"outcome":"lifetime_package_credit","cash_refund_percent":0,"package_credit_eligible":true},"full_voluntary_lt_48h":{"outcome":"forfeited","cash_refund_percent":0,"package_credit_eligible":false},"partial_gte_48h":{"outcome":"cash_refund","cash_refund_percent":100},"partial_lt_48h":{"outcome":"cash_refund","cash_refund_percent":50},"partial_after_day_1":{"outcome":"cash_refund","cash_refund_percent":0},"no_show":{"outcome":"forfeited","cash_refund_percent":0},"flight_disruption_verified":{"outcome":"package_reactivation","recovery_fee_percent":50,"maximum_uses":1},"flight_disruption_unverified":{"outcome":"voluntary_late_cancellation"},"force_majeure_full_tour":{"options":["lifetime_package_credit","cash_refund_less_nonrecoverable_vendor_cost"]},"force_majeure_partial_tour":{"first_remedy":"alternative_route","second_remedy":"affected_component_refund"},"jvto_operational":{"options":["accepted_alternative","full_cash_refund"]}},"partial_thresholds":{"minimum_remaining_pax":2,"minimum_remaining_percent":50,"reprice_remaining_guests":false,"threshold_fail_behaviour":"reclassify_as_full_cancellation","foc_passenger_refund_percent":0},"package_credit_locks":{"expires":false,"cash_value":false,"package_change_allowed":false,"split_allowed":false,"transfer_allowed":true,"maximum_transfers":1,"original_package_locked":true,"original_pax_locked":true,"original_price_locked":true},"booking_scope":{"allowed_sources":["website"],"disallowed_sources":["whatsapp","email","manual","ota"],"support_channels":["whatsapp","email"]}},"customer_copy":{"package_guarantee_summary":"Your confirmed package does not disappear when plans change early. Cancel your entire booking at least 48 hours before Day 1 and the same package, your original number of travellers, and your original confirmed package price remain available for future use as Lifetime Package Credit.","before_48_full_cancellation":"Cancel the complete booking 48 hours or more before Day 1: you receive Lifetime Package Credit. It never expires and preserves the same package, original pax entitlement, and original confirmed price, and can be transferred once. Package Credit is not cash and cannot be exchanged for cash.","after_48_full_cancellation":"Cancel the complete booking less than 48 hours before Day 1: the booking is forfeited and no Package Credit is created.","partial_cancellation":"If one or more travellers cancel but the tour continues, the cancelled travellers receive a cash refund of their confirmed price: 100% at 48 hours or more before Day 1, 50% within 48 hours, and 0% after Day 1. At least 2 paying travellers must remain, otherwise it is treated as a full cancellation.","flight_disruption":"If a verified natural transport disruption (for example volcanic ash) cancels your flight, your package can be reactivated once for a 50% Recovery Fee of the original confirmed package price.","destination_force_majeure":"If a verified official event affects your destination and the whole tour is impossible, you can choose Lifetime Package Credit or a cash refund less any non-recoverable vendor cost. If only part is affected, JVTO first offers an alternative route, then a refund of the affected component.","package_transfer":"Package Credit may be transferred once to another person. The old credit code is closed and a new one is issued to the recipient. A second transfer is not permitted.","package_redemption":"To use Package Credit, choose a new date for the same package. Your original pax entitlement appears automatically; fewer travellers yields no refund, and more travellers are charged the incremental website price."},"adjudicated_facts":{"founding_year":2015,"pt_legal_context":"PT Java Volcano Rendezvous; NIB/TDUP era 2023 (no invented incorporation date)","deposit_percent":20,"close_departure_full_within_days":14,"cancellation_model":"lifetime_package_credit","cancellation_naming":"Lifetime Package Credit (supersedes the retired ''Travel Credit'')","ijen_health_screening":"mandatory","ijen_health_authority":"BBKSDA Surat Edaran SE.1658/KSA.9/2024 (cited as supporting authority, not a conditional trigger)","blue_fire":"natural phenomenon subject to weather and gas activity; cannot be guaranteed","reviews":{"trustpilot":"4.8/51","google":"4.9/123","tripadvisor":"4.95/21","cross_platform":"4.8/195"},"prices":"IDR-only (format: IDR 1,550,000/person)","email_primary":"hello@javavolcano-touroperator.com","email_secondary":"javavolcanotouroperator@gmail.com","phone":"+62 822 4478 8833","nib":"1102230032918","ahu":"-0023020","hq_address":"Jl. Khairil Anwar No.102A, Bondowoso 68214","elevations":{"kawah_ijen_m":2386,"mount_bromo_m":2329}}}'::jsonb, '{"domain":"llm-wiki-policy","summary":"llm-wiki-policy","evidence_count":"llm-wiki-policy","canonical_sources":"llm-wiki-policy","decision_matrix":"llm-wiki-policy","customer_copy":"llm-wiki-policy","adjudicated_facts":"canonical-facts"}'::jsonb, 'llm-wiki-policy', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('policy_document', 'policy_document:ijen-health-screening', 'ijen-health-screening', NULL, '{"domain":"Ijen Health Screening","summary":"Mandatory wording (health certificate required for every guest before crater entry); BBKSDA SE.1658/KSA.9/2024 cited as supporting authority, not a conditional trigger. Adjudicated 2026-07-06, supersedes the 2026-07-05 conditional decision","evidence_count":2,"canonical_sources":["website/faq-master.md","people/dr-ahmad-irwandanu.md"]}'::jsonb, '{"domain":"llm-wiki-policy","summary":"llm-wiki-policy","evidence_count":"llm-wiki-policy","canonical_sources":"llm-wiki-policy"}'::jsonb, 'llm-wiki-policy', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
