INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('public_person_profile', 'public_person_profile:boy', 'boy', 'Boy (Ahboy)', '{"role":"Guide","kta":"KTA-G-2024-004","languages":["EN","ID"],"strengths":"Friendly, safety-first, logistics, great photos, local knowledge","review_count":23,"portrait_url":"https://javavolcano-touroperator.com/uploads/1768228191022-893381041-boy.png","name":"Boy (Ahboy)","bio":"I am a local resident who enjoys welcoming visitors and sharing stories about this area. I''m happy to help travelers explore the natural beauty, local culture, and unique experiences so they feel comfortable and truly enjoy their visit."}'::jsonb, '{"role":"llm-wiki-trust","kta":"llm-wiki-trust","languages":"llm-wiki-trust","strengths":"llm-wiki-trust","review_count":"llm-wiki-trust","portrait_url":"llm-wiki-trust","name":"jvto-db-crew","bio":"jvto-db-crew"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
