INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('public_person_profile', 'public_person_profile:fauzi', 'fauzi', 'Fauzi', '{"role":"Guide","kta":"KTA-G-2024-010","languages":["ID"],"strengths":"Photography, attentive, safety-first, finding uncrowded spots","review_count":6,"portrait_url":"https://javavolcano-touroperator.com/uploads/1768226003889-338819579-fauzi.png","name":"Fauzi","bio":"I''m a friendly guide who loves taking photos for guests and quickly connects with people. I enjoy making trips fun, relaxed, and memorable."}'::jsonb, '{"role":"llm-wiki-trust","kta":"llm-wiki-trust","languages":"llm-wiki-trust","strengths":"llm-wiki-trust","review_count":"llm-wiki-trust","portrait_url":"llm-wiki-trust","name":"jvto-db-crew","bio":"jvto-db-crew"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('public_person_profile', 'public_person_profile:fredi', 'fredi', 'Fredi', '{"role":"Driver","kta":"KTA-D-2024-005","languages":["EN","ID"],"strengths":"Punctuality, safe driving, professional attitude","review_count":20,"portrait_url":"https://javavolcano-touroperator.com/uploads/1768276791622-262250680-freddy.png","name":"Fredi","bio":"Experienced Tour Driver committed to making your travels memorable. I combine safe driving skills with a friendly, helpful attitude to provide a stress-free experience. Whether it''s a short trip or a long tour, I prioritize guest comfort and reliable service at all times."}'::jsonb, '{"role":"llm-wiki-trust","kta":"llm-wiki-trust","languages":"llm-wiki-trust","strengths":"llm-wiki-trust","review_count":"llm-wiki-trust","portrait_url":"llm-wiki-trust","name":"jvto-db-crew","bio":"jvto-db-crew"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('public_person_profile', 'public_person_profile:gufron', 'gufron', 'Gufron', '{"role":"Guide","kta":"KTA-G-2024-001","languages":["EN","ID"],"strengths":"Volcano photography, geology, Ijen crater safety, East Java cultural heritage","review_count":20,"portrait_url":"https://javavolcano-touroperator.com/uploads/1768225567764-405955176-gufron.png","name":"Gufron","bio":"I''m someone who enjoys meaningful conversations on virtually any topic. In my professional life, I place the highest priority on safety and risk management - what some might call strict, I view as a fundamental matter of integrity and responsibility. I have a strong intuitive sense that helps me read situations quickly and accurately. Inside of work, I''m passionate about photography, where I enjoy capturing moments with attention to detail and composition. I''m also an avid music enthusiast with a diverse playlist spanning multiple genres, and I love singing along whenever the mood strikes."}'::jsonb, '{"role":"llm-wiki-trust","kta":"llm-wiki-trust","languages":"llm-wiki-trust","strengths":"llm-wiki-trust","review_count":"llm-wiki-trust","portrait_url":"llm-wiki-trust","name":"jvto-db-crew","bio":"jvto-db-crew"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('public_person_profile', 'public_person_profile:holili', 'holili', 'Holili', '{"role":"Driver","kta":"KTA-D-2024-009","languages":["ID"],"review_count":6,"portrait_url":"https://javavolcano-touroperator.com/uploads/1768277053384-470130286-holili.jpg","name":"Holili","bio":"I am a Java Volcano driver who dedicates myself to serving all Java Volcano customers wholeheartedly."}'::jsonb, '{"role":"llm-wiki-trust","kta":"llm-wiki-trust","languages":"llm-wiki-trust","review_count":"llm-wiki-trust","portrait_url":"llm-wiki-trust","name":"jvto-db-crew","bio":"jvto-db-crew"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
INSERT INTO entities (entity_type, canonical_key, slug, title, data, provenance, source, editable) VALUES ('public_person_profile', 'public_person_profile:joyo', 'joyo', 'Joyo', '{"role":"Driver","kta":"KTA-D-2024-011","languages":["ID"],"review_count":19,"portrait_url":"https://javavolcano-touroperator.com/uploads/1768277336049-911840775-joyo.png","name":"Joyo","bio":"I''m a professional driver who combines speed with precision and care. I drive fast, but always cleanly, smoothly, and safely. My vehicle is kept in impeccable condition inside and out; cleanliness and comfort are non-negotiable for every single ride. Clients frequently tell me I''m their number one choice, \"Customer Number 1\", because they know they''ll get to their destination quickly without ever feeling rushed or unsafe. I take pride in being punctual, reliable, and genuinely attentive to what each passenger needs, whether it''s a daily commute, an important business trip, airport transfer, or a special occasion."}'::jsonb, '{"role":"llm-wiki-trust","kta":"llm-wiki-trust","languages":"llm-wiki-trust","review_count":"llm-wiki-trust","portrait_url":"llm-wiki-trust","name":"jvto-db-crew","bio":"jvto-db-crew"}'::jsonb, 'llm-wiki-trust', false) ON CONFLICT (canonical_key) DO UPDATE SET data = EXCLUDED.data, provenance = EXCLUDED.provenance, title = EXCLUDED.title, source = EXCLUDED.source, updated_at = now();
