INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 4, 'page_content', 'live', '{"h1":"Private East Java Tours: Surabaya & Bali Departures","faq":[{"a":"Yes. The route logic across JVTO is private by default, with your own vehicle and your own route flow rather than a shared-tour structure.","q":"Are all JVTO tours private?"},{"a":"Usually by departure point first. Surabaya and Bali create different route logic, transfer patterns, and timing assumptions even when the destinations overlap.","q":"Should I choose by destination or by departure point first?"},{"a":"Read the Ijen Health Screening page so the route seriousness is understood before you commit to timing or expectations.","q":"What should I do before choosing an Ijen route?"}],"lede":["Start with the operator trust that makes JVTO different, then choose the route shape that fits your departure logic, timing, and seriousness level."],"sections":[{"copy":"Short routes stay focused. Multi-day routes add contrast, but they also ask for more honest attention to pacing and route fit.","items":[{"copy":"Best for guests who want a clear Bromo or Ijen objective without turning the trip into a broader East Java circuit.","title":"1-2 Day Focused Routes"},{"copy":"Best for guests who want the strongest volcano combinations while still keeping the trip manageable and logically structured.","title":"3-4 Day Balanced Routes"},{"copy":"Best for travelers who want East Java to feel like a full journey rather than a compressed checklist of iconic stops.","title":"5-6 Day Discovery Routes"}],"title":"Choose by Duration"},{"copy":"Some tours are volcano-led, some are overland, and some are broader nature routes. The right route is the one that fits your timing, energy, and priorities.","items":[{"copy":"Built around Bromo, Ijen, or a strong Bromo-Ijen combination for travelers who want the volcanic landscapes to stay central.","title":"Volcano-Led"},{"copy":"Mixes volcanoes with waterfalls or coastline for guests who want stronger visual variety and a wider East Java narrative.","title":"Nature Contrast"},{"copy":"Designed for travelers starting in one city or island and finishing in another with route continuity, not fragmented logistics.","title":"Overland Transition"}],"title":"Choose by Route Style"}],"body_md":"# JVTO Private Volcano Tours\n\nChoose a private, all-inclusive East Java volcano tour by starting point.\n\n## From Surabaya\n- [1D1N Bromo Midnight](/tours/from-surabaya/bromo-1d1n) — from IDR 1,000,000 per person\n- [2D1N Bromo Sunrise + Madakaripura](/tours/from-surabaya/bromo-2d1n) — from IDR 1,750,000 per person\n- [3D2N Bromo + Madakaripura + Ijen (Surabaya–Bali overland)](/tours/from-surabaya/bromo-madakaripura-ijen-3d2n) — from IDR 2,450,000 per person\n- [2D1N Ijen Blue Fire Expedition](/tours/from-surabaya/ijen-2d1n) — from IDR 1,550,000 per person\n- [3D2N Ijen + Bromo + Madakaripura (Surabaya–Surabaya)](/tours/from-surabaya/ijen-bromo-madakaripura-3d2n) — from IDR 2,450,000 per person\n- [4D3N Ijen + Bromo + Madakaripura Expedition (Surabaya–Surabaya)](/tours/from-surabaya/ijen-bromo-madakaripura-4d3n) — from IDR 3,025,000 per person\n- [5D4N Ijen + Bromo + Madakaripura + Malang (Surabaya–Surabaya)](/tours/from-surabaya/ijen-bromo-madakaripura-malang-5d4n) — from IDR 3,850,000 per person\n- [4D3N Ijen + Papuma + Tumpak Sewu + Bromo (Surabaya–Surabaya)](/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-4d3n) — from IDR 3,125,000 per person\n- [5D4N Full East Java Circuit (Surabaya–Surabaya)](/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-5d4n) — from IDR 3,650,000 per person\n- [6D5N Grand East Java (Surabaya–Surabaya)](/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-malang-6d5n) — from IDR 4,750,000 per person\n- [3D2N Taman Safari Prigen + Bromo + Madakaripura (Specialty)](/tours/from-surabaya/taman-safari-prigen-bromo-madakaripura-3d2n) — from IDR 3,450,000 per person\n- [4D3N Tumpak Sewu + Bromo + Ijen (Surabaya–Bali overland)](/tours/from-surabaya/tumpak-sewu-bromo-ijen-4d3n) — from IDR 3,125,000 per person\n\n## From Bali\n- [3D2N Bromo + Ijen (Bali–Bali)](/tours/from-bali/bromo-ijen-3d2n) — from IDR 2,850,000 per person\n- [3D2N Ijen + Bromo + Madakaripura (Bali–Surabaya)](/tours/from-bali/ijen-bromo-madakaripura-3d2n) — from IDR 2,850,000 per person\n- [4D3N Full Circuit (Bali–Surabaya)](/tours/from-bali/ijen-papuma-tumpak-sewu-bromo-4d3n) — from IDR 3,475,000 per person\n- [5D4N Full Circuit Extended (Bali–Surabaya)](/tours/from-bali/ijen-papuma-tumpak-sewu-bromo-5d4n) — from IDR 4,050,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
