INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Private Tours from Surabaya","faq":[{"a":"For many East Java itineraries, yes. It offers efficient access to both short and longer private routes with less cross-island complexity than Bali starts.","q":"Is Surabaya the best starting point for most routes?"},{"a":"Yes. Some Surabaya departures are intentionally built as overland journeys that finish in Bali instead of returning to the starting point.","q":"Can I still end in Bali?"},{"a":"Use your available days first, then filter by route seriousness. If Ijen is on the shortlist, read the health guide before narrowing the final choice.","q":"What should I do next?"}],"lede":["Surabaya is the strongest mainland entry when guests want route flexibility, clearer airport logic, and the widest range of private East Java package shapes."],"links":[{"href":"/tours/from-surabaya/1-day-bromo-midnight-experience","label":"1 Day Bromo Midnight Experience","description":"Best for travelers who want a focused Bromo route from Surabaya without turning the trip into a multi-day circuit."},{"href":"/tours/from-surabaya/2-day-ijen-blue-fire-expedition","label":"2 Day Ijen Blue Fire Expedition","description":"Best for guests who want Ijen handled as the main route priority and not diluted into a rushed combination."},{"href":"/tours/from-surabaya/3-day-ijen-bromo-madakaripura","label":"3 Day Ijen, Bromo & Madakaripura","description":"Best for travelers who want the strongest three-day balance of volcanoes and waterfall contrast."},{"href":"/tours/from-surabaya/5-day-east-java-overland-to-bali","label":"5 Day East Java Overland to Bali","description":"Best for guests who want a longer Surabaya-to-Bali route with broader East Java narrative and continuity."}],"sections":[{"copy":"Surabaya routes are often the cleanest place to start because they combine route range with stronger mainland timing control and easier package comparison.","items":[{"copy":"Surabaya gives the clearest spread from focused Bromo and Ijen routes to broader East Java overland journeys.","title":"Widest Package Range"},{"copy":"For many guests, Surabaya reduces early cross-island friction and makes route planning easier before commitment.","title":"Cleaner Airport Logic"},{"copy":"It is often the easiest origin to compare short, balanced, and overland route families without changing the whole travel logic first.","title":"Better Comparison Starting Point"}],"title":"Why Surabaya Works So Well"},{"copy":"The most popular Surabaya departures combine Bromo and Ijen, with longer routes adding waterfalls, coastline, or Malang.","items":[{"copy":"A compressed but disciplined Bromo option for guests with limited time who still want a strong sunrise-oriented route flow.","title":"1 Day Bromo Midnight Experience"},{"copy":"A focused Ijen route for travelers who want one destination handled seriously, including screening logic and night-oriented timing.","title":"2 Day Ijen Blue Fire Expedition"},{"copy":"A balanced East Java sequence combining volcanic seriousness with waterfall atmosphere in a route that feels full without sprawling.","title":"3 Day Ijen, Bromo & Madakaripura"}],"title":"Popular Route Families"},{"copy":"Short private routes work best for guests with limited time who still want clear handling and a focused destination experience.","items":[{"copy":"Short Surabaya departures suit travelers landing in East Java who want fast access to a core highlight without adding unnecessary complexity.","title":"Best for Tight Schedules"},{"copy":"A shorter route works when you care more about a clean Bromo or Ijen experience than collecting multiple stops.","title":"Best for Destination Focus"}],"title":"Short Trips"},{"copy":"Longer routes give guests a fuller East Java story, but they should be chosen carefully based on energy, transfer comfort, and interest in variety.","items":[{"copy":"Good for guests who want contrast in the trip rather than a pure volcano-only structure.","title":"Volcano + Waterfall"},{"copy":"Good for guests who want East Java to feel broader and more visually varied, with a more active route profile.","title":"Volcano + Coastline + Waterfall"},{"copy":"Good for travelers who want to start in Surabaya and finish in Bali through a structured eastward route rather than backtracking.","title":"Overland to Bali"}],"title":"Multi-Day Overland Routes"},{"copy":"Every route page has exact details, but the system stays consistent: private transport, clear route handling, and less logistical guesswork.","items":[{"copy":"The route is organized around your group rather than a pooled guest structure.","title":"Private by Default"},{"copy":"Transfers, timing, and route transitions are treated as part of the product, not left to the guest to improvise.","title":"Clear Handling"},{"copy":"If a route includes Ijen, Bromo cold exposure, or more serious terrain, that reality should be explained before you choose the route.","title":"Planning Before Hype"}],"title":"What Stays Consistent"}],"readingLinks":[{"href":"/travel-guide/booking-information","label":"Read Booking Information","description":"See how private booking works before you narrow down your route choice."},{"href":"/travel-guide/packing-and-fitness","label":"Read Packing & Fitness","description":"Use this before choosing longer or more physically varied Surabaya departures."},{"href":"/travel-guide/ijen-health-screening","label":"Read the Ijen Health Guide","description":"If Ijen is part of your route shortlist, this should be read before date discussions."}]}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'section_head', NULL, '{"title":"From Bali"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-bali' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'card_grid', 'tour', '{}'::jsonb, ARRAY['package:bali-bromo-ijen-3d2n','package:bali-ijen-bromo-madakaripura-3d2n','package:bali-ijen-papuma-tumpak-sewu-bromo-4d3n','package:bali-ijen-papuma-tumpak-sewu-bromo-5d4n']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-bali' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Private Tours from Bali","faq":[{"a":"Yes. JVTO tours are private by default, including Bali departures and cross-island overland handling.","q":"Are Bali routes private too?"},{"a":"Not always. Some Bali-origin routes are intentionally designed to finish in Surabaya after the East Java segment.","q":"Do Bali routes end back in Bali?"},{"a":"Choose your available days first, then decide whether you want a clean volcano route or a broader East Java overland journey.","q":"What should I do next?"}],"lede":["Bali departures are built for guests who want East Java without piecing the harder cross-island movement together themselves. They work best when route continuity is part of the value."],"links":[{"href":"/tours/from-bali/3-day-bromo-ijen-volcano-discovery","label":"3 Day Bromo & Ijen Volcano Discovery","description":"Best for travelers who want the cleanest Bali-origin volcano route without expanding into a broader circuit."},{"href":"/tours/from-bali/3-day-ijen-bromo-madakaripura","label":"3 Day Ijen, Bromo & Madakaripura","description":"Best for guests who want compact variety and a stronger East Java feel inside a short Bali-origin route."},{"href":"/tours/from-bali/5-day-east-java-overland-discovery","label":"5 Day East Java Overland Discovery","description":"Best for travelers who want Bali-to-Surabaya continuity with more room for contrast and route breadth."}],"sections":[{"copy":"Bali-origin routes are more convincing when guests understand that ferry movement, timing control, and volcano access are being handled as one managed private system.","items":[{"copy":"The trip begins before the volcanoes. Good Bali routes remove transfer confusion instead of leaving guests to stitch together the hard parts.","title":"Cross-Island Handling Is Part Of The Product"},{"copy":"Because the route crosses islands and often includes Ijen, proof-backed operator handling matters more than generic itinerary beauty.","title":"Trust Matters More Here"},{"copy":"Some Bali routes are strongest because they do not loop back. They finish in Surabaya and turn East Java into a managed travel sequence.","title":"Forward-Moving Journeys Are A Real Advantage"}],"title":"Why Bali Routes Need Stronger Operator Trust"},{"copy":"The most popular Bali routes combine Bromo and Ijen, with longer journeys adding Papuma Beach and Tumpak Sewu before ending in Surabaya.","items":[{"copy":"The cleanest Bali-origin volcano route for travelers who mainly want the strongest two-volcano combination with private handling.","title":"3 Day Bromo & Ijen Volcano Discovery"},{"copy":"Adds waterfall atmosphere to the core cross-island volcano structure while keeping the route understandable and efficient.","title":"3 Day Ijen, Bromo & Madakaripura"},{"copy":"A broader Bali-to-Surabaya journey for travelers who want the route itself to feel like part of the experience, not just transfer overhead.","title":"4-5 Day East Java Overland Discovery"}],"title":"Popular Route Families"},{"copy":"Short Bali departures offer a focused cross-island route for guests who want the core volcano experience without turning it into a full East Java circuit.","items":[{"copy":"A shorter Bali start works when you want a guided entry into East Java without committing to a long and varied itinerary.","title":"Best for First-Time East Java Guests"},{"copy":"Bali routes are strongest when they remove ferry and timing confusion rather than asking guests to self-coordinate the hard parts.","title":"Best for Clear Transfer Logic"}],"title":"Short Trips"},{"copy":"Longer departures from Bali are ideal for guests who want the journey itself to be part of the experience.","items":[{"copy":"A strong option for guests who want to keep moving forward instead of looping back after the East Java segment.","title":"Bali to Surabaya Finish"},{"copy":"These routes work best for travelers who actively want coastline, waterfall, and volcano contrast rather than pure destination minimalism.","title":"Destination-Rich Itineraries"},{"copy":"The longer the route and the more varied the terrain, the more important honest preparation becomes before confirming dates.","title":"Serious Preparation Required"}],"title":"Multi-Day Overland Routes"},{"copy":"Private handling matters even more on Bali-origin routes because ferry, transfer, and timing complexity can build quickly when the route is not structured well.","items":[{"copy":"The route is designed as one coherent private flow rather than a patchwork of separate transport assumptions.","title":"Private Route Continuity"},{"copy":"The Bali-to-East-Java transition is part of the product value, not an afterthought left to guesswork.","title":"Cross-Island Clarity"},{"copy":"Bromo cold exposure, Ijen screening, and longer overland pacing should be understood before route selection becomes emotional rather than practical.","title":"Preparation Before Confirmation"}],"title":"What Stays Consistent"}],"readingLinks":[{"href":"/travel-guide/booking-information","label":"Read Booking Information","description":"Use this to understand how JVTO handles route planning and confirmation before choosing a Bali start."},{"href":"/travel-guide/ijen-health-screening","label":"Read the Ijen Health Guide","description":"Essential if your Bali route shortlist includes Ijen."},{"href":"/travel-guide/weather-and-closures","label":"Read the Weather & Closure Guide","description":"Helpful for guests who want to understand how route changes are handled across volcanic and overland segments."}]}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-bali' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/isic/student-package' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'live', '{"h1":"ISIC Student Package","sections":[{"id":"eligibility","title":"Eligibility & Verification","bullets":["Valid ISIC card required","Lead guest identity must match booking record","Verification may be requested again before departure"],"paragraphs":["Student packages are available for selected routes and dates only.","Guests must provide a valid ISIC identity and matching personal information before voucher issuance."]},{"id":"coverage","title":"What Student Packages Include","bullets":["Private transport and driver for booked route","Route-specific permits and operational support where listed","Accommodation and meals as written in the chosen package","Ijen screening inclusion for routes containing Ijen night hike (when applicable)"],"paragraphs":["Inclusions depend on the selected itinerary and are confirmed in writing in your quotation and Official E-Voucher."]},{"id":"how-to-claim","title":"How to Claim Student Pricing","bullets":["Choose a qualifying tour on /tours","Submit ISIC details during enquiry/booking step","Receive final verified quote and payment link","Booking is confirmed only after payment and voucher issuance"],"paragraphs":["Use the official flow below to avoid booking delays."]},{"id":"policy-linkage","items":[{"route":"/policy/booking-payment-cancellation","title":"Booking, Payment & Cancellation Policy"},{"route":"/verify-jvto","title":"Verify JVTO credentials"},{"route":"/travel-guide/ijen-health-screening","title":"Ijen Health Screening guide"}],"title":"Policy and Trust References","paragraphs":["Student pricing changes commercial terms, not safety or legal standards. All bookings remain bound by the same policy framework and verification architecture."]}],"cross_links":{"tours":"/tours","policy":"/policy/booking-payment-cancellation","verify":"/verify-jvto","contact":"/contact","booking_information":"/travel-guide/booking-information"},"intro_paragraphs":["JVTO collaborates with ISIC to provide selected student-focused packages for eligible cardholders. This page explains who qualifies, what documents are required, and how student pricing is applied.","Student pricing is valid only after identity and card verification. Final booking terms still follow your Official E-Voucher and the Booking, Payment & Cancellation Policy."],"body_md":"# Student Packages — ISIC Verified\n\n## Hero\n\nJVTO is an official ISIC provider (Provider ID 259268). If you hold a valid ISIC card, you have access to student-priced East Java volcano tours — same private vehicle, same licensed guide, same all-inclusive format as the standard packages, at reduced per-person rates.\n\nStudent pricing is verified at checkout via the Alive Verify API. Your card must be valid and current. No card, no discount — no exceptions.\n\n---\n\n## What Is ISIC?\n\nThe International Student Identity Card (ISIC) is the only internationally recognised student identity document, endorsed by UNESCO and accepted in 130+ countries. It confirms full-time student status for enrolled students — card validity is confirmed via the Alive Verify API at the time of booking.\n\nISIC verifies provider eligibility through its Alive Verify API — a real-time authentication check. JVTO is a registered provider in the ISIC network: [isic.org/discounts/?providerId=259268](https://www.isic.org/discounts/?providerId=259268).\n\nIf you are not yet an ISIC cardholder, cards are issued through national student unions and ISIC offices worldwide. Visit [isic.org](https://www.isic.org) to apply.\n\n---\n\n## How ISIC Verification Works at JVTO\n\n1. Share your ISIC card number when you book on the JVTO website.\n2. JVTO runs an Alive Verify API check against the ISIC database.\n3. If the card returns valid, student pricing is confirmed for your booking.\n4. Card must be valid on the date of verification — not just on travel date.\n\nNo workarounds. The API check is live and automated.\n\n---\n\n## Student Package Pricing\n\nSix ISIC-eligible packages are available. All prices are per person in IDR. All packages are 100% private — dedicated vehicle, driver, and English-speaking guide. No shared groups.\n\n---\n\n### 3D2N Bromo + Ijen (Surabaya origin, return to Surabaya or to Bali)\n\nRoute: `tours/student-package/bromo-ijen-3d2n` and `bromo-ijen-3d2n-to-bali`\n\n| Group size | IDR/person |\n|---|---|\n| 1 (solo) | 5,400,000 |\n| 2 | 3,050,000 |\n| 3 | 2,850,000 |\n| 4–5 | 2,650,000 |\n| 6–7 | 2,450,000 |\n| 8–10 | 2,250,000 |\n| 11+ | 2,050,000 |\n\n---\n\n### 3D2N Ijen + Bromo (Bali origin)\n\nRoute: `tours/student-package/ijen-bromo-3d2n`\n\n| Group size | IDR/person |\n|---|---|\n| 2 | 2,900,000 |\n| 3 | 2,700,000 |\n| 4–5 | 2,500,000 |\n| 6–7 | 2,300,000 |\n| 8–10 | 2,100,000 |\n| 11+ | 1,900,000 |\n\n---\n\n### 4D3N Ijen + Bromo + Madakaripura + Night Market (Surabaya origin)\n\nRoute: `tours/student-package/ijen-bromo-madakaripura-night-market-4d3n`\n\n| Group size | IDR/person |\n|---|---|\n| 1 (solo) | 6,500,000 |\n| 2 | 3,700,000 |\n| 3 | 3,500,000 |\n| 4–5 | 3,300,000 |\n| 6–7 | 3,100,000 |\n| 8–10 | 2,900,000 |\n| 11+ | 2,700,000 |\n\n---\n\n### 4D3N Ijen + Papuma + Tumpak Sewu + Bromo (Surabaya origin)\n\nRoute: `tours/student-package/ijen-papuma-tumpak-sewu-bromo-4d3n`\n\n| Group size | IDR/person |\n|---|---|\n| 1 (solo) | 7,150,000 |\n| 2 | 4,100,000 |\n| 3 | 3,900,000 |\n| 4–5 | 3,600,000 |\n| 6–7 | 3,350,000 |\n| 8–10 | 3,000,000 |\n| 11+ | 2,900,000 |\n\n---\n\n### 5D4N Ijen + Papuma + Tumpak Sewu + Bromo (Surabaya origin)\n\nRoute: `tours/student-package/ijen-papuma-tumpak-sewu-bromo-5d4n`\n\n| Group size | IDR/person |\n|---|---|\n| 2 | 4,050,000 |\n| 3 | 3,850,000 |\n| 4–5 | 3,650,000 |\n| 6–7 | 3,450,000 |\n| 8–10 | 3,250,000 |\n| 11+ | 3,050,000 |\n\n*Solo pricing: not available for this package. Minimum 2 pax.*\n\n---\n\n## What''s Included — Same as Standard Packages\n\nStudent packages carry the same inclusions as the canonical JVTO packages:\n\n- Private vehicle and driver for the full duration\n- English-speaking licensed guide\n- Hotel accommodation with breakfast\n- All entrance fees\n- Drinking water throughout\n- Parking, fuel, road tolls\n- Gas masks on Ijen-inclusive routes\n- Bromo 4WD jeep on Bromo-inclusive routes\n- Mandatory health-certificate screening coordination for every guest on Ijen routes (BBKSDA SE.1658/KSA.9/2024)\n\n**Not included**: international flights, travel insurance, personal trekking gear, tips, optional on-site extras (horse riding at Bromo, trolley ojek at Ijen).\n\n---\n\nNote: Packages marked ''Night Market'' include an evening local market visit in the East Java itinerary.\n\n---\n\n## Book a Student Package\n\nSend your ISIC card number and intended travel dates via WhatsApp. We will run the verification check and confirm pricing.\n\n**WhatsApp: +62 822 4478 8833**\n[Message us →](https://wa.me/6282244788833)\n\nJVTO is operated by PT Java Volcano Rendezvous, NIB 1102230032918, Bondowoso, East Java."}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/isic/student-package' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
