INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"3 Day Bromo & Ijen Volcano Discovery from Bali","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"2 pax","price_formatted":"IDR 4,050,000","price_idr_per_pax":4050000},{"group":"3 pax","price_formatted":"IDR 3,800,000","price_idr_per_pax":3800000},{"group":"4-5 pax","price_formatted":"IDR 3,550,000","price_idr_per_pax":3550000},{"group":"6-7 pax","price_formatted":"IDR 3,350,000","price_idr_per_pax":3350000},{"group":"8-10 pax","price_formatted":"IDR 3,050,000","price_idr_per_pax":3050000},{"group":"11+ pax","price_formatted":"IDR 2,850,000","price_idr_per_pax":2850000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Ijen world-famous blue fire phenomenon","Iconic Bromo sunrise with Milky Way stargazing","Cross-island adventure from Bali to Java","Round-trip back to Bali"],"route_meta":{"duration":"3D2N","end_city":"Bali","start_city":"Bali","perfect_for":["Adventure seekers","Nature lovers","Volcano enthusiasts","Photography enthusiasts","Active travelers"],"physicality":"moderate","destinations":["Kawah Ijen","Mount Bromo","Madakaripura Waterfall"],"ideal_arrival":"10:00","last_day_safe_flight":"After 19:00 from Bali"}},{"id":"itinerary","days":[{"day":1,"title":"Marathon Expedition: From Bali Beaches to Mount Bromo","summary":"Get ready for an epic day of travel! This route is designed for true adventurers, taking you from Bali, across the strait, and straight on to a long overland journey across East Java to Mount Bromo. You''ll witness the most dramatic landscape changes in a single day."},{"day":2,"title":"From Bromo Sunrise to Canyon Waterfalls and Onward to Ijen","summary":"This is one of the most intense connection days in the itinerary. After witnessing sunrise and exploring Bromo, you continue to the lush canyon of Madakaripura for a refreshing waterfall trek before driving deep into the highlands of Bondowoso. Upon arrival, a mandatory health check is carried out at your hotel to clear you for the Ijen climb the n"},{"day":3,"title":"Leaving the Volcanoes Behind: Crossing from Ijen to Bali","summary":"After your final breakfast in the Ijen area, we drive you down to Ketapang Harbor to board the ferry to Bali. Enjoy the sea views during the short crossing before continuing overland to your hotel in southern Bali, where your volcano adventure gives way to island relaxation."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Good physical fitness for challenging treks","Printed passport for Ijen permit","Warm clothing (5–15°C)","Sturdy hiking shoes","No respiratory conditions"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management","Ferry tickets: Ketapang Harbour → Gilimanuk Harbour (Bali)"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Adventure seekers and nature lovers.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 3D2N Bromo + Ijen (Bali–Bali)\n\nPrivate 3D2N tour from Bali, covering mount-bromo, kawah-ijen.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,050,000 per person\n- 3 pax: IDR 3,800,000 per person\n- 4–5 pax: IDR 3,550,000 per person\n- 6–7 pax: IDR 3,350,000 per person\n- 8–10 pax: IDR 3,050,000 per person\n- 11–null pax: IDR 2,850,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-bali/bromo-ijen-3d2n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
