INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"3 Day Ijen, Bromo & Madakaripura Waterfall Journey from Bali to Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"Solo Traveler","price_formatted":"IDR 7,500,000","price_idr_per_pax":7500000},{"group":"2 pax","price_formatted":"IDR 4,050,000","price_idr_per_pax":4050000},{"group":"3 pax","price_formatted":"IDR 3,800,000","price_idr_per_pax":3800000},{"group":"4-5 pax","price_formatted":"IDR 3,550,000","price_idr_per_pax":3550000},{"group":"6-7 pax","price_formatted":"IDR 3,350,000","price_idr_per_pax":3350000},{"group":"8-10 pax","price_formatted":"IDR 3,050,000","price_idr_per_pax":3050000},{"group":"11+ pax","price_formatted":"IDR 2,850,000","price_idr_per_pax":2850000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Convenient Bali departure with ferry crossing","Ijen blue fire before sunrise","Iconic Bromo sunrise over volcanic caldera","Serene Madakaripura waterfall in lush canyon"],"route_meta":{"duration":"3D2N","end_city":"Surabaya","start_city":"Bali","perfect_for":["Couples seeking adventure","Bali-based travelers","Cross-island explorers","Romantic getaway seekers"],"physicality":"moderate","destinations":["Kawah Ijen","Mount Bromo","Madakaripura Waterfall"],"ideal_arrival":"10:00","last_day_safe_flight":"After 19:00 from Surabaya"}},{"id":"itinerary","days":[{"day":1,"title":"Cross-Strait Adventure: From Bali to Banyuwangi (Ijen Area)","summary":"Your unique adventure begins with a road trip across the western part of Bali to Gilimanuk Harbor. Upon arrival in Banyuwangi, after check-in, medical personnel will visit you at your hotel for a convenient medical check-up, before enjoying a awaited dinner."},{"day":2,"title":"From Two Peaks: Ijen Adventure Continues to Mount Bromo","summary":"After conquering Ijen, your adventure continues west. Enjoy our prepared lunch to refuel before embarking on the long overland journey to the majestic volcanic landscape of Bromo."},{"day":3,"title":"Two Icons in One Day: Bromo & Madakaripura, Back to Surabaya","summary":"A day that combines the majesty of Bromo with the splendor of Madakaripura. After enjoying the sunrise, the adventure continues with a refreshing trek through the canyon of the legendary Madakaripura Waterfall, before we return you to Surabaya."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate fitness","Printed passport for Ijen permit","Warm clothing (5–15°C)","Sturdy hiking shoes and water shoes","Ijen health screening mandatory"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management","Ferry tickets: Ketapang Harbour → Gilimanuk Harbour (Bali)"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Couples seeking adventure and natural beauty.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 3D2N Ijen + Bromo + Madakaripura (Bali–Surabaya)\n\nPrivate 3D2N tour from Bali, covering kawah-ijen, mount-bromo, madakaripura.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,050,000 per person\n- 3 pax: IDR 3,800,000 per person\n- 4–5 pax: IDR 3,550,000 per person\n- 6–7 pax: IDR 3,350,000 per person\n- 8–10 pax: IDR 3,050,000 per person\n- 11–null pax: IDR 2,850,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-bali/ijen-bromo-madakaripura-3d2n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
