INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"4 Day Ijen, Papuma Beach, Tumpak Sewu & Bromo Expedition from Bali to Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"Solo Traveler","price_formatted":"IDR 9,050,000","price_idr_per_pax":9050000},{"group":"2 pax","price_formatted":"IDR 4,900,000","price_idr_per_pax":4900000},{"group":"3 pax","price_formatted":"IDR 4,700,000","price_idr_per_pax":4700000},{"group":"4-5 pax","price_formatted":"IDR 4,400,000","price_idr_per_pax":4400000},{"group":"6-7 pax","price_formatted":"IDR 4,100,000","price_idr_per_pax":4100000},{"group":"8-10 pax","price_formatted":"IDR 3,625,000","price_idr_per_pax":3625000},{"group":"11+ pax","price_formatted":"IDR 3,475,000","price_idr_per_pax":3475000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Ijen turquoise sulfuric crater lake and blue fire","Papuma Beach stunning sunset over unique rock formations","Tumpak Sewu magnificent curtain-like waterfall","Iconic Bromo sunrise with Milky Way stargazing"],"route_meta":{"duration":"4D3N","end_city":"Surabaya","start_city":"Bali","perfect_for":["Adventure seekers","Nature lovers","Active travelers","First-time Java visitors","Landscape photographers"],"physicality":"moderate","destinations":["Kawah Ijen","Mount Bromo","Papuma Beach"],"ideal_arrival":"10:00","last_day_safe_flight":"After 19:00"}},{"id":"itinerary","days":[{"day":1,"title":"Cross-Strait Adventure: From Bali to Banyuwangi (Ijen Area)","summary":"Your unique adventure begins with a road trip across the western part of Bali to Gilimanuk Harbor. Upon arrival in Banyuwangi, after check-in, medical personnel will visit you at your hotel for a convenient medical check-up, before enjoying a awaited dinner."},{"day":2,"title":"From the Blue Fire of Ijen to the Golden Sunset of Papuma","summary":"Today was a mix of extreme adventure and relaxation. We began with a climb to Ijen, followed by lunch to recharge. Afterward, we headed south to the coast to close the day with a sunset at Papuma Beach."},{"day":3,"title":"Onward Transfer: From Jember to Tumpak Sewu Area","summary":"After breakfast at your Jember hotel and perhaps some free time, the journey continues in the afternoon. This route connects downtown Jember with the rural areas of Lumajang, setting you up in a prime location for your Tumpak Sewu Waterfall adventure the next day."},{"day":4,"title":"Mount Bromo and Return to Surabaya''s Civilization","summary":"The day begins with a magical sunrise over Mount Bromo. After a volcanic adventure and a hearty breakfast, we''ll drive you back down the mountains to Surabaya, concluding your adventure."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate to high fitness","Printed passport for Ijen permit","Warm clothing (5–15°C)","Sturdy hiking shoes and water shoes"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management","Ferry tickets: Ketapang Harbour → Gilimanuk Harbour (Bali)"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Adventure seekers, nature lovers, and active travelers.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 4D3N Full Circuit (Bali–Surabaya)\n\nPrivate 4D3N tour from Bali, covering kawah-ijen, papuma-beach, tumpak-sewu, mount-bromo.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,900,000 per person\n- 3 pax: IDR 4,700,000 per person\n- 4–5 pax: IDR 4,400,000 per person\n- 6–7 pax: IDR 4,100,000 per person\n- 8–10 pax: IDR 3,625,000 per person\n- 11–null pax: IDR 3,475,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-bali/ijen-papuma-tumpak-sewu-bromo-4d3n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
