INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"1 Day Bromo Midnight Experience from Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"2 pax","price_formatted":"IDR 1,550,000","price_idr_per_pax":1550000},{"group":"3-4 pax","price_formatted":"IDR 1,400,000","price_idr_per_pax":1400000},{"group":"5-7 pax","price_formatted":"IDR 1,250,000","price_idr_per_pax":1250000},{"group":"8-10 pax","price_formatted":"IDR 1,050,000","price_idr_per_pax":1050000},{"group":"11+ pax","price_formatted":"IDR 1,000,000","price_idr_per_pax":1000000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Midnight departure for optimal sunrise timing at Kingkong Hill","Vintage 4WD Jeep experience to sunrise viewpoint","Bromo crater exploration with sulfur smoke views","Whispering Sand mystical landscape discovery","Complete experience returning to Surabaya by noon"],"route_meta":{"duration":"1D1N","end_city":"Surabaya","start_city":"Surabaya","perfect_for":["Time-constrained travelers","Nature lovers","Adventure seekers","Photography enthusiasts","Weekend explorers"],"physicality":"moderate","destinations":["Mount Bromo"],"ideal_arrival":"00:00","last_day_safe_flight":"After 14:00 on tour day"}},{"id":"itinerary","days":[{"day":1,"title":"Overnight Adventure in Bromo: Midnight Departure from Surabaya","summary":"Forget the hotel and sleep on the road! This quick adventure picks you up from Surabaya at midnight and takes you through the darkness straight to the foot of Mount Bromo. You''ll switch to a 4WD Jeep for an off-road adventure, witness a magical sunrise, climb the crater, and return to Surabaya in the afternoon. This is an intense and highly efficie"}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate fitness for stair climbing and sand walking","Warm clothing (5–15°C)","Sturdy hiking shoes","Small daypack for essentials","Ability to handle midnight start and early morning activities"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Full assistance: arrival to final drop-off","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management","Complimentary JVTO travel T-shirt (1 per participant)"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Nature lovers and adventure seekers looking for a compact yet comprehensive volcanic landscape experience.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 1D1N Bromo Midnight\n\nPrivate 1D1N tour from Surabaya, covering mount-bromo.\n\n## Pricing (private, per person)\n- 2 pax: IDR 1,550,000 per person\n- 3–4 pax: IDR 1,400,000 per person\n- 5–7 pax: IDR 1,250,000 per person\n- 8–10 pax: IDR 1,050,000 per person\n- 11–null pax: IDR 1,000,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/bromo-1d1n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
