INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"2 Day Bromo Sunrise Adventure from Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"2 pax","price_formatted":"IDR 2,800,000","price_idr_per_pax":2800000},{"group":"3 pax","price_formatted":"IDR 2,550,000","price_idr_per_pax":2550000},{"group":"4-5 pax","price_formatted":"IDR 2,350,000","price_idr_per_pax":2350000},{"group":"6-7 pax","price_formatted":"IDR 2,150,000","price_idr_per_pax":2150000},{"group":"8-10 pax","price_formatted":"IDR 1,950,000","price_idr_per_pax":1950000},{"group":"11+ pax","price_formatted":"IDR 1,750,000","price_idr_per_pax":1750000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Iconic Bromo sunrise with Milky Way stargazing","4WD Jeep adventure across the volcanic sand sea","Visit Java''s highest waterfall at Madakaripura","Perfect short escape from Surabaya with maximum impact"],"route_meta":{"duration":"2D1N","end_city":"Surabaya","start_city":"Surabaya","perfect_for":["Adventure seekers","Nature lovers","Time-constrained travelers","First-time Java visitors","Photography enthusiasts"],"physicality":"moderate","destinations":["Mount Bromo","Madakaripura Waterfall"],"ideal_arrival":"15:00","last_day_safe_flight":"After 19:00"}},{"id":"itinerary","days":[{"day":1,"title":"Gateway to the Clouds: Your Journey from Surabaya to Mount Bromo","summary":"Your adventure begins when we pick you up from Surabaya. Enjoy a comfortable ride as the scenery changes from the city to the cool Tengger mountains. You''ll feel the temperature drop, signaling your arrival at Cemoro Lawang, a magical village on the rim of the Bromo crater."},{"day":2,"title":"Two Icons in One Day: Bromo & Madakaripura, Back to Surabaya","summary":"A day that combines the majesty of Bromo with the splendor of Madakaripura. After enjoying the sunrise, the adventure continues with a refreshing trek through the canyon of the legendary Madakaripura Waterfall, before we return you to Surabaya."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate fitness","Warm clothing (5–15°C)","Sturdy hiking shoes and water shoes","Small daypack","Early morning wake-up capability"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Adventure and nature lovers seeking a quick, memorable escape.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 2D1N Bromo Sunrise + Madakaripura\n\nPrivate 2D1N tour from Surabaya, covering mount-bromo, madakaripura.\n\n## Pricing (private, per person)\n- 2 pax: IDR 2,800,000 per person\n- 3 pax: IDR 2,550,000 per person\n- 4–5 pax: IDR 2,350,000 per person\n- 6–7 pax: IDR 2,150,000 per person\n- 8–10 pax: IDR 1,950,000 per person\n- 11–null pax: IDR 1,750,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/bromo-2d1n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
