INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"2 Day Ijen Blue Fire Expedition from Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"2 pax","price_formatted":"IDR 2,300,000","price_idr_per_pax":2300000},{"group":"3 pax","price_formatted":"IDR 2,200,000","price_idr_per_pax":2200000},{"group":"4-5 pax","price_formatted":"IDR 2,050,000","price_idr_per_pax":2050000},{"group":"6-7 pax","price_formatted":"IDR 1,850,000","price_idr_per_pax":1850000},{"group":"8-10 pax","price_formatted":"IDR 1,650,000","price_idr_per_pax":1650000},{"group":"11+ pax","price_formatted":"IDR 1,550,000","price_idr_per_pax":1550000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Witness the world-famous Ijen blue fire phenomenon before sunrise","See the stunning turquoise sulfuric crater lake at dawn","Observe local sulfur miners at work in extreme conditions","Visit Malabar Coffee Plantation for authentic Arabica coffee"],"route_meta":{"duration":"2D1N","end_city":"Surabaya","start_city":"Surabaya","perfect_for":["Adventure seekers","Nature lovers","Photography enthusiasts","Geology enthusiasts","Active travelers"],"physicality":"moderate","destinations":["Kawah Ijen"],"ideal_arrival":"12:00","last_day_safe_flight":"After 20:00"}},{"id":"itinerary","days":[{"day":1,"title":"Towards the Ijen Plateau: Overland Travel from Surabaya to Bondowoso","summary":"This long journey is the perfect transition from the hustle and bustle of Surabaya to the tranquility of the mountains. After arriving and checking in, a medical professional will come to your hotel for a brief, comfortable health check. Afterward, enjoy a well-prepared dinner to conclude your day."},{"day":2,"title":"From Highlands to City Lights: Ijen Area to Surabaya","summary":"Say goodbye to the Ijen highlands and settle in for a scenic drive across East Java. After a long but comfortable journey, you will arrive back in Surabaya, ready for your next flight or an extra night in the city."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate fitness for steep 1.5–2 hour trek","Printed passport copy for Ijen permit","Warm clothing (5–15°C)","Sturdy hiking shoes","No respiratory conditions (sulfur exposure)"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Adventure seekers looking for a compact yet immersive experience.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 2D1N Ijen Blue Fire Expedition\n\nPrivate 2D1N tour from Surabaya, covering kawah-ijen.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 2,300,000 per person\n- 3 pax: IDR 2,200,000 per person\n- 4–5 pax: IDR 2,050,000 per person\n- 6–7 pax: IDR 1,850,000 per person\n- 8–10 pax: IDR 1,650,000 per person\n- 11–null pax: IDR 1,550,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/ijen-2d1n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
