INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"5 Day Ijen, Bromo, Madakaripura & Malang City Adventure from Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"2 pax","price_formatted":"IDR 5,250,000","price_idr_per_pax":5250000},{"group":"3 pax","price_formatted":"IDR 5,050,000","price_idr_per_pax":5050000},{"group":"4-5 pax","price_formatted":"IDR 4,750,000","price_idr_per_pax":4750000},{"group":"6-7 pax","price_formatted":"IDR 4,450,000","price_idr_per_pax":4450000},{"group":"8-10 pax","price_formatted":"IDR 4,050,000","price_idr_per_pax":4050000},{"group":"11+ pax","price_formatted":"IDR 3,850,000","price_idr_per_pax":3850000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Ijen blue fire before sunrise","Stargazing and sunrise over Bromo","4WD Jeep across Sea of Sand","Madakaripura waterfall in mystical canyon","Rainbow Village and Batu City exploration"],"route_meta":{"duration":"5D4N","end_city":"Surabaya","start_city":"Surabaya","perfect_for":["Active travelers","First-time Java visitors","Nature photographers","Adventure seekers"],"physicality":"moderate","destinations":["Kawah Ijen","Mount Bromo","Madakaripura Waterfall"],"ideal_arrival":"12:00","last_day_safe_flight":"After 14:00"}},{"id":"itinerary","days":[{"day":1,"title":"Towards the Ijen Plateau: Overland Travel from Surabaya to Bondowoso","summary":"This long journey is the perfect transition from the hustle and bustle of Surabaya to the tranquility of the mountains. After arriving and checking in, a medical professional will come to your hotel for a brief, comfortable health check. Afterward, enjoy a well-prepared dinner to conclude your day."},{"day":2,"title":"From Two Peaks: Ijen Adventure Continues to Mount Bromo","summary":"After conquering Ijen, your adventure continues west. Enjoy our prepared lunch to refuel before embarking on the long overland journey to the majestic volcanic landscape of Bromo."},{"day":3,"title":"Volcanoes, Waterfall Canyon, and City Comfort: Bromo & Madakaripura to Malang","summary":"Start the day with a breathtaking sunrise at Bromo and a visit to the crater. Continue with a dramatic canyon walk at Madakaripura Waterfall before heading to Malang, where you can unwind in a cooler city atmosphere after a full day of adventure."},{"day":4,"title":"The Last Charm of Malang and Return to Surabaya","summary":"Enjoy the morning exploring the various tourist attractions in Batu and Malang. After a satisfying photo-op and adventure, continue your journey back to Surabaya, either to stay overnight or directly to the airport for your flight home."},{"day":5,"title":"Convenient Delivery to Juanda Airport","summary":"After enjoying your final breakfast at the hotel, take advantage of some free time before we pick you up for a quiet and stress-free transfer to Juanda International Airport (SUB) for your onward flight."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate fitness for night trek","Printed passport for Ijen permit","Warm clothing (5–15°C)","Sturdy hiking shoes and water shoes","Rain jacket/poncho for waterfalls"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Travelers seeking both excitement and discovery.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 5D4N Ijen + Bromo + Madakaripura + Malang (Surabaya–Surabaya)\n\nPrivate 5D4N tour from Surabaya, covering kawah-ijen, mount-bromo, madakaripura, malang.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 5,250,000 per person\n- 3 pax: IDR 5,050,000 per person\n- 4–5 pax: IDR 4,750,000 per person\n- 6–7 pax: IDR 4,450,000 per person\n- 8–10 pax: IDR 4,050,000 per person\n- 11–null pax: IDR 3,850,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/ijen-bromo-madakaripura-malang-5d4n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.se