INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"4 Day Ijen, Papuma Beach, Tumpak Sewu & Bromo Journey from Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"Solo Traveler","price_formatted":"IDR 8,050,000","price_idr_per_pax":8050000},{"group":"2 pax","price_formatted":"IDR 4,550,000","price_idr_per_pax":4550000},{"group":"3 pax","price_formatted":"IDR 4,350,000","price_idr_per_pax":4350000},{"group":"4-5 pax","price_formatted":"IDR 4,050,000","price_idr_per_pax":4050000},{"group":"6-7 pax","price_formatted":"IDR 3,750,000","price_idr_per_pax":3750000},{"group":"8-10 pax","price_formatted":"IDR 3,275,000","price_idr_per_pax":3275000},{"group":"11+ pax","price_formatted":"IDR 3,125,000","price_idr_per_pax":3125000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Ijen blue fire before sunrise","Pristine Papuma Beach with white sands and dramatic rocks","Tumpak Sewu multi-tiered waterfall","Iconic Bromo sunrise over volcanic caldera"],"route_meta":{"duration":"4D3N","end_city":"Surabaya","start_city":"Surabaya","perfect_for":["Nature enthusiasts","Young explorers","Beach and volcano lovers","Photography enthusiasts"],"physicality":"moderate","destinations":["Kawah Ijen","Mount Bromo","Papuma Beach"],"ideal_arrival":"12:00","last_day_safe_flight":"After 18:00"}},{"id":"itinerary","days":[{"day":1,"title":"Towards the Ijen Plateau: Overland Travel from Surabaya to Bondowoso","summary":"This long journey is the perfect transition from the hustle and bustle of Surabaya to the tranquility of the mountains. After arriving and checking in, a medical professional will come to your hotel for a brief, comfortable health check. Afterward, enjoy a well-prepared dinner to conclude your day."},{"day":2,"title":"From the Blue Fire of Ijen to the Golden Sunset of Papuma","summary":"Today was a mix of extreme adventure and relaxation. We began with a climb to Ijen, followed by lunch to recharge. Afterward, we headed south to the coast to close the day with a sunset at Papuma Beach."},{"day":3,"title":"Onward Transfer: From Jember to Tumpak Sewu Area","summary":"After breakfast at your Jember hotel and perhaps some free time, the journey continues in the afternoon. This route connects downtown Jember with the rural areas of Lumajang, setting you up in a prime location for your Tumpak Sewu Waterfall adventure the next day."},{"day":4,"title":"Mount Bromo and Return to Surabaya''s Civilization","summary":"The day begins with a magical sunrise over Mount Bromo. After a volcanic adventure and a hearty breakfast, we''ll drive you back down the mountains to Surabaya, concluding your adventure."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate fitness for multiple treks","Printed passport for Ijen permit","Warm clothing (5–15°C) and beachwear","Sturdy hiking shoes and water shoes","Ijen health screening mandatory"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Nature enthusiasts and young explorers.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 4D3N Ijen + Papuma + Tumpak Sewu + Bromo (Surabaya–Surabaya)\n\nPrivate 4D3N tour from Surabaya, covering kawah-ijen, papuma-beach, tumpak-sewu, mount-bromo.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,550,000 per person\n- 3 pax: IDR 4,350,000 per person\n- 4–5 pax: IDR 4,050,000 per person\n- 6–7 pax: IDR 3,750,000 per person\n- 8–10 pax: IDR 3,275,000 per person\n- 11–null pax: IDR 3,125,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-4d3n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
