INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"6 Day Ijen, Papuma Beach, Tumpak Sewu, Bromo & Malang City Discovery from Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"2 pax","price_formatted":"IDR 6,050,000","price_idr_per_pax":6050000},{"group":"3 pax","price_formatted":"IDR 5,750,000","price_idr_per_pax":5750000},{"group":"4-5 pax","price_formatted":"IDR 5,550,000","price_idr_per_pax":5550000},{"group":"6-7 pax","price_formatted":"IDR 5,250,000","price_idr_per_pax":5250000},{"group":"8-10 pax","price_formatted":"IDR 4,950,000","price_idr_per_pax":4950000},{"group":"11+ pax","price_formatted":"IDR 4,750,000","price_idr_per_pax":4750000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Ijen blue fire before sunrise","Stargazing and sunrise over Bromo","Tumpak Sewu thousand-stream waterfall","Papuma Beach sunset","Batu City exploration with Rainbow Village"],"route_meta":{"duration":"6D5N","end_city":"Surabaya","start_city":"Surabaya","perfect_for":["Adventure seekers","Nature lovers","Cultural explorers","Photography enthusiasts"],"physicality":"moderate","destinations":["Kawah Ijen","Mount Bromo","Malang","Papuma Beach"],"ideal_arrival":"12:00","last_day_safe_flight":"After 14:00"}},{"id":"itinerary","days":[{"day":1,"title":"Towards the Ijen Plateau: Overland Travel from Surabaya to Bondowoso","summary":"This long journey is the perfect transition from the hustle and bustle of Surabaya to the tranquility of the mountains. After arriving and checking in, a medical professional will come to your hotel for a brief, comfortable health check. Afterward, enjoy a well-prepared dinner to conclude your day."},{"day":2,"title":"From the Blue Fire of Ijen to the Golden Sunset of Papuma","summary":"Today was a mix of extreme adventure and relaxation. We began with a climb to Ijen, followed by lunch to recharge. Afterward, we headed south to the coast to close the day with a sunset at Papuma Beach."},{"day":3,"title":"Onward Transfer: From Jember to Tumpak Sewu Area","summary":"After breakfast at your Jember hotel and perhaps some free time, the journey continues in the afternoon. This route connects downtown Jember with the rural areas of Lumajang, setting you up in a prime location for your Tumpak Sewu Waterfall adventure the next day."},{"day":4,"title":"From Volcanic Landscapes to the Charm of Cool Cities: Bromo to Malang","summary":"After an epic adventure on Mount Bromo, enjoy a scenic descent to Malang, a city known for its cool air and creative atmosphere. It''s a seamless transition from wilderness to urban comfort."},{"day":5,"title":"A Day Full of Color: A Creative Exploration of Batu City, Malang","summary":"Start the day with breakfast at the hotel, then get ready for a fun day tour exploring the best photo spots and unique attractions in the cool Batu area, from colorful villages, modern flower gardens, to apple picking agrotourism."},{"day":6,"title":"Convenient Delivery to Juanda Airport","summary":"After enjoying your final breakfast at the hotel, take advantage of some free time before we pick you up for a quiet and stress-free transfer to Juanda International Airport (SUB) for your onward flight."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate to good fitness","Printed passport for Ijen permit","Warm clothing (5–15°C)","Sturdy hiking shoes and water shoes","Rain jacket/poncho for waterfalls"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Those looking to explore Malang''s cultural and natural attractions.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 6D5N Grand East Java (Surabaya–Surabaya)\n\nPrivate 6D5N tour from Surabaya, covering kawah-ijen, papuma-beach, tumpak-sewu, mount-bromo, malang.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 6,050,000 per person\n- 3 pax: IDR 5,750,000 per person\n- 4–5 pax: IDR 5,550,000 per person\n- 6–7 pax: IDR 5,250,000 per person\n- 8–10 pax: IDR 4,950,000 per person\n- 11–null pax: IDR 4,750,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/ijen-papuma-tumpak-sewu-bromo-malang-6d5n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
