INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"3 Day Taman Safari Prigen, Bromo & Madakaripura Family Tour from Surabaya","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"2 pax","price_formatted":"IDR 4,350,000","price_idr_per_pax":4350000},{"group":"3 pax","price_formatted":"IDR 4,150,000","price_idr_per_pax":4150000},{"group":"4-5 pax","price_formatted":"IDR 3,950,000","price_idr_per_pax":3950000},{"group":"6-7 pax","price_formatted":"IDR 3,750,000","price_idr_per_pax":3750000},{"group":"8-10 pax","price_formatted":"IDR 3,550,000","price_idr_per_pax":3550000},{"group":"11+ pax","price_formatted":"IDR 3,450,000","price_idr_per_pax":3450000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Guided safari at Taman Safari Prigen","Iconic Bromo sunrise with Milky Way stargazing","Madakaripura waterfall — Java''s highest — in mystical canyon","Family-friendly activities for all ages"],"route_meta":{"duration":"3D2N","end_city":"Surabaya","start_city":"Surabaya","perfect_for":["Families with children","Wildlife enthusiasts","Nature lovers","First-time Java visitors","Multi-generational travel"],"physicality":"easy","destinations":["Taman Safari Prigen","Mount Bromo","Madakaripura Waterfall"],"ideal_arrival":"12:00","last_day_safe_flight":"After 19:00"}},{"id":"itinerary","days":[{"day":1,"title":"From Wildlife to Volcano Peak: Safari Park Tour & Onward to Bromo","summary":"A perfect day for a double adventure! Starting in Surabaya, you''ll explore Prigen Safari Park, interacting with wildlife up close. In the afternoon, continue your journey uphill to Mount Bromo, ready for the next day''s sunrise adventure."},{"day":2,"title":"From Wildlife to Volcano Peak: Safari Park Tour & Onward to Bromo","summary":"A perfect day for a double adventure! Starting in Surabaya, you''ll explore Prigen Safari Park, interacting with wildlife up close. In the afternoon, continue your journey uphill to Mount Bromo, ready for the next day''s sunrise adventure."},{"day":3,"title":"Two Icons in One Day: Bromo & Madakaripura, Back to Surabaya","summary":"A day that combines the majesty of Bromo with the splendor of Madakaripura. After enjoying the sunrise, the adventure continues with a refreshing trek through the canyon of the legendary Madakaripura Waterfall, before we return you to Surabaya."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Minimal to moderate fitness","Warm clothing (5–15°C for Bromo)","Comfortable walking shoes","Water shoes for Madakaripura","Small daypack"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Families with children, wildlife enthusiasts, nature lovers, first-time Java visitors.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 3D2N Taman Safari Prigen + Bromo + Madakaripura (Specialty)\n\nPrivate 3D2N tour from Surabaya, covering taman-safari-prigen, mount-bromo, madakaripura.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,350,000 per person\n- 3 pax: IDR 4,150,000 per person\n- 4–5 pax: IDR 3,950,000 per person\n- 6–7 pax: IDR 3,750,000 per person\n- 8–10 pax: IDR 3,550,000 per person\n- 11–null pax: IDR 3,450,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/taman-safari-prigen-bromo-madakaripura-3d2n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
