INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 9, 'page_content', 'live', '{"h1":"4 Day Tumpak Sewu, Bromo & Ijen Adventure from Surabaya to Bali","sections":[{"id":"pricing","note":"Prices are per person. Group size determines the per-person rate — larger groups pay less per person.","title":"Pricing — per person (IDR)","currency":"IDR","price_table":[{"group":"Solo Traveler","price_formatted":"IDR 8,050,000","price_idr_per_pax":8050000},{"group":"2 pax","price_formatted":"IDR 4,550,000","price_idr_per_pax":4550000},{"group":"3 pax","price_formatted":"IDR 4,350,000","price_idr_per_pax":4350000},{"group":"4-5 pax","price_formatted":"IDR 4,050,000","price_idr_per_pax":4050000},{"group":"6-7 pax","price_formatted":"IDR 3,750,000","price_idr_per_pax":3750000},{"group":"8-10 pax","price_formatted":"IDR 3,275,000","price_idr_per_pax":3275000},{"group":"11+ pax","price_formatted":"IDR 3,125,000","price_idr_per_pax":3125000}],"contact_to_book":"To confirm availability and book: WhatsApp +6282244788833 or email hello@javavolcano-touroperator.com"},{"id":"overview","title":"Tour overview","highlights":["Tumpak Sewu magnificent multi-tiered waterfall","Bromo iconic sunrise across volcanic sand sea","Ijen rare blue fire phenomenon and turquoise crater lake","One-way adventure Surabaya to Bali"],"route_meta":{"duration":"4D3N","end_city":"Bali","start_city":"Surabaya","perfect_for":["Nature lovers","Young explorers","Adventure seekers","Photography enthusiasts","Active travelers"],"physicality":"moderate","destinations":["Mount Bromo","Tumpak Sewu Waterfall","Kawah Ijen"],"ideal_arrival":"12:00","last_day_safe_flight":"After 14:00"}},{"id":"itinerary","days":[{"day":1,"title":"The Path to Waterfall Paradise: The Journey from Surabaya to Tumpak Sewu","summary":"This journey from Surabaya will take you south, passing through small towns and plantations, experiencing the authentic East Javanese countryside before arriving in Lumajang, home to the magnificent Tumpak Sewu."},{"day":2,"title":"From the Hidden Paradise of Tumpak Sewu to the Land Above the Clouds of Bromo","summary":"Your morning will be filled with an unforgettable trekking adventure to the base of Tumpak Sewu Waterfall. Afterward, enjoy a well-prepared lunch before continuing the dramatic climb into the volcanic landscape of Bromo."},{"day":3,"title":"From Two Peaks: The Bromo Adventure Continues to the Foot of Ijen","summary":"After witnessing the majesty of Bromo, your adventure continues east. This overland journey will take you to the Bondowoso highlands. Upon arrival, you''ll undergo a comfortable mandatory medical check-up at your hotel before enjoying a hearty dinner."},{"day":4,"title":"Leaving the Volcanoes Behind: Crossing from Ijen to Bali","summary":"After your final breakfast in the Ijen area, we drive you down to Ketapang Harbor to board the ferry to Bali. Enjoy the sea views during the short crossing before continuing overland to your hotel in southern Bali, where your volcano adventure gives way to island relaxation."}],"title":"Day-by-day itinerary"},{"id":"requirements","title":"What you need to bring and know","bullets":["Moderate to good fitness","Printed passport for Ijen permit","Warm clothing (5–15°C)","Sturdy hiking shoes and water shoes","No respiratory conditions"]},{"id":"includes","title":"What is included","bullets":["Private transport: AC vehicle (MPV 1–3 guests, Minibus 4–11), driver, fuel, tolls, parking","Tour guides: English-speaking. Driver-guide for 1–3 pax; separate local guide at each destination for 4+","Mineral water: daily supply","Complimentary JVTO travel T-shirt (1 per participant)","Full assistance: arrival to final drop-off","Hotel accommodation: quality hotels, daily breakfast included","All entrance fees and permits","Meals as stated in itinerary","Private 4WD Jeep for Bromo sunrise tour","Ijen health screening: doctor check evening before trek (passport only required)","Trekking equipment: gas masks + trekking poles (Ijen); helmets at Madakaripura by local management","Ferry tickets: Ketapang Harbour → Gilimanuk Harbour (Bali)"]},{"id":"excludes","title":"What is not included","bullets":["International/domestic air tickets","Indonesian VISA (if applicable)","Travel insurance (recommended)","Meals not stated in itinerary (own expense)","Personal expenses: snacks, souvenirs, beverages (carry min IDR 500,000/person)","Tips for drivers and guides (at discretion)"]}],"cross_links":{"verify":"/verify-jvto","contact":"/contact","packing":"/travel-guide/packing-and-fitness","tours_hub":"/tours","ijen_health":"/travel-guide/ijen-health-screening","booking_info":"/travel-guide/booking-information"},"intro_paragraphs":["Nature lovers and young explorers.","All-inclusive: private transport, accommodation, all entrance fees and permits, English-speaking guides, and meals as stated in the itinerary.","Official channels: Website https://javavolcano-touroperator.com • WhatsApp +6282244788833 • Email hello@javavolcano-touroperator.com."],"body_md":"# 4D3N Tumpak Sewu + Bromo + Ijen (Surabaya–Bali overland)\n\nPrivate 4D3N tour from Surabaya, covering tumpak-sewu, mount-bromo, kawah-ijen.\n\nA medical health screening is mandatory for every guest before Kawah Ijen crater entry, per BBKSDA SE.1658/KSA.9/2024 — included in the price.\n\n## Pricing (private, per person)\n- 2 pax: IDR 4,550,000 per person\n- 3 pax: IDR 4,350,000 per person\n- 4–5 pax: IDR 4,050,000 per person\n- 6–7 pax: IDR 3,750,000 per person\n- 8–10 pax: IDR 3,275,000 per person\n- 11–null pax: IDR 3,125,000 per person"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/tours/from-surabaya/tumpak-sewu-bromo-ijen-4d3n' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
