INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 5, 'card_grid', 'package', '{}'::jsonb, ARRAY['package:bali-bromo-ijen-3d2n','package:bali-ijen-bromo-madakaripura-3d2n','package:bali-ijen-papuma-tumpak-sewu-bromo-4d3n','package:bali-ijen-papuma-tumpak-sewu-bromo-5d4n','package:surabaya-bromo-1d1n','package:surabaya-bromo-2d1n','package:surabaya-bromo-madakaripura-ijen-3d2n','package:surabaya-ijen-bromo-madakaripura-3d2n','package:surabaya-ijen-bromo-madakaripura-4d3n','package:surabaya-ijen-bromo-madakaripura-malang-5d4n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-4d3n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-5d4n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-malang-6d5n','package:surabaya-taman-safari-prigen-bromo-madakaripura-3d2n','package:surabaya-tumpak-sewu-bromo-ijen-4d3n']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/destinations/mount-bromo' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
