INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 6, 'card_grid', 'package', '{}'::jsonb, ARRAY['package:bali-bromo-ijen-3d2n','package:bali-ijen-bromo-madakaripura-3d2n','package:bali-ijen-papuma-tumpak-sewu-bromo-4d3n','package:bali-ijen-papuma-tumpak-sewu-bromo-5d4n','package:surabaya-bromo-madakaripura-ijen-3d2n','package:surabaya-ijen-2d1n','package:surabaya-ijen-bromo-madakaripura-3d2n','package:surabaya-ijen-bromo-madakaripura-4d3n','package:surabaya-ijen-bromo-madakaripura-malang-5d4n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-4d3n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-5d4n','package:surabaya-ijen-papuma-tumpak-sewu-bromo-malang-6d5n','package:surabaya-tumpak-sewu-bromo-ijen-4d3n']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/destinations/ijen-crater' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 7, 'gallery', 'destination', '{"title":"Kawah Ijen (Ijen Crater) gallery"}'::jsonb, '{}'::text[], ARRAY['destination-photo/ijen-crater/01','destination-photo/ijen-crater/02','destination-photo/ijen-crater/03','destination-photo/ijen-crater/04','destination-photo/ijen-crater/05','destination-photo/ijen-crater/06','destination-photo/ijen-crater/07','destination-photo/ijen-crater/08','destination-photo/ijen-crater/09','destination-photo/ijen-crater/10','destination-photo/ijen-crater/11','destination-photo/ijen-crater/12','destination-photo/ijen-crater/13']::text[], false FROM pages p WHERE p.route = '/destinations/ijen-crater' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 8, 'page_content', 'live', '{"h1":"Kawah Ijen (Ijen Crater)","body_md":"# Kawah Ijen (Ijen Crater)\n\n**Meta description:**\nKawah Ijen is an active volcano at 2,386 m with the world''s highest-volume acidic crater lake. Famous for the pre-dawn blue fire sulfuric-gas phenomenon — visible only in suitable weather and gas conditions. Access from Paltuding trailhead via a steep ~3 km night hike. BBKSDA East Java is the regulatory authority.\n\n## Overview\nKawah Ijen is an active volcano at 2,386 m with the world''s highest-volume acidic crater lake. Famous for the pre-dawn blue fire sulfuric-gas phenomenon — visible only in suitable weather and gas conditions. Access from Paltuding trailhead via a steep ~3 km night hike. BBKSDA East Java is the regulatory authority.\n\nVolcano on Banyuwangi-Bondowoso border at 2,386 m. World-famous for rare blue fire phenomenon from igniting sulfuric gases and turquoise acidic crater lake.\n\n## Quick Facts\n- **Elevation:** 2,386 m\n- **Location:** Banyuwangi / Bondowoso Regency, East Java, Indonesia\n- **Type:** Active stratovolcano\n- **Difficulty:** Moderate\n- **Best season:** Dry season: April–October\n- **Access:** Night hike from Paltuding trailhead (~3 km, ~90 min ascent)\n- **Crater lake:** Turquoise, highly acidic (≈ pH 0) — highest-volume acidic crater lake on Earth\n- **Famous for:** Blue fire phenomenon, acidic lake, sulfur mining\n- **Regulatory authority:** BBKSDA East Java — https://bbksdajatim.org\n\n## Best Time to Visit\nMay–October (dry season). Begin trek at 01:00–02:00 AM for blue fire and sunrise.\n\nDry Season (May–October): 10°C–20°C, ideal trekking. Wet Season: 12°C–22°C, higher humidity, muddy trails.\n\n## The Trail\n~6 km round trip. 1.5–2 hours to crater rim. Optional 30-min rocky descent to blue fire site and lake shore.\n\nModerate fitness for 3–4 hour steep hike. Not suitable for severe asthma or respiratory issues.\n\n## What to See\nBlue fire phenomenon (visible midnight–04:00 AM), turquoise acidic crater lake, sunrise volcanic vistas.\n\n## The Blue Fire\nBlue Fire is a natural phenomenon subject to weather and gas activity.\n\n## Health Certificate Coordination\nA health certificate is mandatory for every guest before Kawah Ijen crater entry per BBKSDA SE.1658/KSA.9/2024. JVTO coordinates the mandatory clinic workflow. See the full protocol at [Ijen Health Screening](/travel-guide/ijen-health-screening).\n\n## Gear & Tips\n**Gear:** Thermal layers, waterproof jacket, sturdy trekking boots, gas mask (for sulfur fumes), headlamp, warm hat.\n\n**Tips:** Pack gas mask (essential at crater). Wear warm, waterproof layers. Avoid trekking alone. Bring snacks and water.","elevation_m":2386,"source":"llm-wiki:trust-bundle/destinations#kawah-ijen"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/destinations/ijen-crater' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
