INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 6, 'gallery', 'destination', '{"title":"Tumpak Sewu Waterfall (Air Terjun Tumpak Sewu) gallery"}'::jsonb, '{}'::text[], ARRAY['destination-photo/tumpak-sewu-waterfall/01','destination-photo/tumpak-sewu-waterfall/02','destination-photo/tumpak-sewu-waterfall/03','destination-photo/tumpak-sewu-waterfall/04','destination-photo/tumpak-sewu-waterfall/05','destination-photo/tumpak-sewu-waterfall/06','destination-photo/tumpak-sewu-waterfall/07','destination-photo/tumpak-sewu-waterfall/08','destination-photo/tumpak-sewu-waterfall/09','destination-photo/tumpak-sewu-waterfall/10','destination-photo/tumpak-sewu-waterfall/11','destination-photo/tumpak-sewu-waterfall/12','destination-photo/tumpak-sewu-waterfall/13','destination-photo/tumpak-sewu-waterfall/14','destination-photo/tumpak-sewu-waterfall/15','destination-photo/tumpak-sewu-waterfall/16','destination-photo/tumpak-sewu-waterfall/17','destination-photo/tumpak-sewu-waterfall/18','destination-photo/tumpak-sewu-waterfall/19','destination-photo/tumpak-sewu-waterfall/20','destination-photo/tumpak-sewu-waterfall/21','destination-photo/tumpak-sewu-waterfall/22','destination-photo/tumpak-sewu-waterfall/23','destination-photo/tumpak-sewu-waterfall/24','destination-photo/tumpak-sewu-waterfall/25','destination-photo/tumpak-sewu-waterfall/26','destination-photo/tumpak-sewu-waterfall/27','destination-photo/tumpak-sewu-waterfall/28','destination-photo/tumpak-sewu-waterfall/29','destination-photo/tumpak-sewu-waterfall/30','destination-photo/tumpak-sewu-waterfall/31','destination-photo/tumpak-sewu-waterfall/32']::text[], false FROM pages p WHERE p.route = '/destinations/tumpak-sewu-waterfall' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 7, 'page_content', 'live', '{"h1":"Tumpak Sewu Waterfall (Air Terjun Tumpak Sewu)","body_md":"# Tumpak Sewu Waterfall (Air Terjun Tumpak Sewu)\n\n**Meta description:**\nTumpak Sewu is a multi-tiered canyon waterfall (~120 m) in Lumajang, East Java. Nicknamed ''Java''s Niagara'' for its curtain of streams cascading over a curved cliff face into a canyon. Accessed via rim viewpoint or steep canyon descent (~300 steps).\n\n## Overview\nTumpak Sewu is a multi-tiered canyon waterfall (~120 m) in Lumajang, East Java. Nicknamed ''Java''s Niagara'' for its curtain of streams cascading over a curved cliff face into a canyon. Accessed via rim viewpoint or steep canyon descent (~300 steps).\n\n120-meter tiered waterfall between Lumajang-Malang regencies. Unique curtain-like flow across 120-meter width. Near Semeru volcano.\n\n## Quick Facts\n- **Location:** Lumajang Regency, East Java, Indonesia\n- **Type:** Multi-tiered curtain waterfall\n- **Difficulty:** Moderate\n\n## Best Time to Visit\nMay–October (dry season). Morning for best light and fewer crowds.\n\nDry Season (May–October): 22°C–30°C, clear skies. Wet Season: Frequent rain, slippery trails.\n\n## The Trail\n~1 km round trip. 30–45 min descent on steep, slippery path with bamboo ladders and rocky sections.\n\nModerate fitness. Steep descent and wet rocky terrain. Not suitable for those with knee problems.\n\n## What to See\nHorseshoe-shaped multi-tiered waterfall, Kapas Biru downstream pool, Semeru volcano backdrop.\n\n## Gear & Tips\n**Gear:** Quick-dry clothing, non-slip shoes/sandals, poncho, waterproof bag for valuables, trekking poles optional.\n\n**Tips:** Hire local guide (required). Wear waterproof footwear. Avoid after heavy rain.","source":"llm-wiki:trust-bundle/destinations#tumpak-sewu"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/destinations/tumpak-sewu-waterfall' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
