INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 6, 'gallery', 'destination', '{"title":"Madakaripura Waterfall (Air Terjun Madakaripura) gallery"}'::jsonb, '{}'::text[], ARRAY['destination-photo/madakaripura-waterfall/01','destination-photo/madakaripura-waterfall/02','destination-photo/madakaripura-waterfall/03','destination-photo/madakaripura-waterfall/04','destination-photo/madakaripura-waterfall/05','destination-photo/madakaripura-waterfall/06','destination-photo/madakaripura-waterfall/07','destination-photo/madakaripura-waterfall/08','destination-photo/madakaripura-waterfall/09']::text[], false FROM pages p WHERE p.route = '/destinations/madakaripura-waterfall' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 7, 'page_content', 'live', '{"h1":"Madakaripura Waterfall (Air Terjun Madakaripura)","body_md":"# Madakaripura Waterfall (Air Terjun Madakaripura)\n\n**Meta description:**\nMadakaripura is Java''s tallest waterfall in Probolinggo, East Java. A narrow canyon gorge leads to a horseshoe curtain waterfall fed from multiple directions. Historical context: said to be the final meditation site of Gajah Mada, Majapahit prime minister. Easy ~20 min trek from roadside parking.\n\n## Overview\nMadakaripura is Java''s tallest waterfall in Probolinggo, East Java. A narrow canyon gorge leads to a horseshoe curtain waterfall fed from multiple directions. Historical context: said to be the final meditation site of Gajah Mada, Majapahit prime minister. Easy ~20 min trek from roadside parking.\n\n200-meter waterfall in Probolinggo. Tallest on Java Island and second-tallest in Indonesia. Located within Bromo Tengger Semeru National Park buffer zone.\n\n## Quick Facts\n- **Location:** Probolinggo Regency, East Java, Indonesia\n- **Type:** Horseshoe curtain waterfall in narrow canyon\n- **Difficulty:** Moderate\n- **Access:** Easy ~20 min trek from roadside parking (~1.5 km canyon walk); horse option available\n\n## Best Time to Visit\nMay–October. Morning or early afternoon for best light.\n\nDry Season (May–October): Best for visits with safer, less slippery trails. Wet Season: Higher water flow but muddy, hazardous paths.\n\n## The Trail\n~1 km trail; ~30 minutes walk to waterfall. Rocky paths, river crossings, must navigate water cascades near fall.\n\nModerate fitness. Requires balance on wet rocky terrain. Not suitable for those with mobility issues.\n\n## What to See\n200 m tall horseshoe waterfall, cave-like cliffsides, mystical jungle atmosphere.\n\n## Gear & Tips\n**Gear:** Quick-dry clothing, waterproof bag, water shoes/sandals, poncho (expect to get fully wet), snacks.\n\n**Tips:** WILL get wet. Bring dry change of clothes. Avoid during/after heavy rain due to flash flood risk.","source":"llm-wiki:trust-bundle/destinations#madakaripura"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/destinations/madakaripura-waterfall' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
