INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 7, 'page_content', 'live', '{"h1":"Papuma Beach (Pantai Papuma)","body_md":"# Papuma Beach (Pantai Papuma)\n\n**Meta description:**\nPapuma Beach in Jember offers white sand and dramatic coastal rock formations. JVTO includes it as a coastal contrast stop on Papuma-family packages (4D+). Best for guests who want a beach break on an otherwise volcano-focused East Java itinerary.\n\n## Overview\nPapuma Beach in Jember offers white sand and dramatic coastal rock formations. JVTO includes it as a coastal contrast stop on Papuma-family packages (4D+). Best for guests who want a beach break on an otherwise volcano-focused East Java itinerary.\n\nPopular beach in Jember Regency. Name abbreviates ''Pasir Putih Malikan'' (Malikan White Sand). Located in Lojejer Village, Wuluhan.\n\n## Quick Facts\n- **Elevation:** 86 m (cape headland)\n- **Location:** Jember Regency, East Java, Indonesia\n- **Type:** White-sand beach with rocky cape (Tanjung Papuma)\n- **Difficulty:** Easy\n\n## Best Time to Visit\nMay–October. Late afternoon for sunset views.\n\nDry Season (May–October): Clear skies, 24°C–32°C. Wet Season: Occasional rain, rough sea.\n\n## The Trail\nPaved path to beach. Optional short hike to Siti Hinggil Hill viewpoint (20–30 min).\n\nMinimal. Suitable for all ages.\n\n## What to See\nKarst limestone cliff formations, crystal clear water, Siti Hinggil Hill panoramic view, sunset views.\n\n## Gear & Tips\n**Gear:** Light clothing, sandals, sunscreen, hat, water, camera.\n\n**Tips:** Bring cash for local food stalls. Avoid swimming in rough conditions.","elevation_m":{"beach":0,"cape_headland":86},"source":"llm-wiki:trust-bundle/destinations#papuma-beach"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/destinations/papuma-beach' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
