INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'live', '{"h1":"Verify JVTO — Legal","body_md":"# Verify JVTO — Legal\n\nAll registration records and credentials listed below are independently verifiable. SHA-256 hashes are published in `public/llms.txt` on the JVTO website for forensic integrity checks.\n\n---\n\n## Business Registration\n\n| Credential | Number / Value | Issued | Verification URL |\n|---|---|---|---|\n| **Legal name** | PT Java Volcano Rendezvous | — | https://ahu.go.id/pencarian/perseroan |\n| **NIB** (Nomor Induk Berusaha) | 1102230032918 | — | https://oss.go.id |\n| **TDUP** (Tanda Daftar Usaha Pariwisata) | 1102230032918 | 2023-02-11 | https://oss.go.id (Sistem Tanda Daftar OSS) |\n\n---\n\n## KBLI Business Activity Codes\n\n| KBLI Code | Activity Description |\n|---|---|\n| **79121** | Travel Agency (Agen Perjalanan Wisata) |\n| **79911** | Tour Operator (Penyelenggara Wisata) |\n| **62019** | Other computer programming / IT services |\n| **79120** | Travel agency activities (related) |\n| **79921** | Tour guide activities (Pemanduan Wisata) |\n\n---\n\n## Tourism & Safety Credentials\n\n| Credential | Identifier | Issuing Authority | Function |\n|---|---|---|---|\n| **HPWKI** | AHU-0001072.AH.01.07.TAHUN 2024 | State-recognized association (AHU) | Himpunan Pelaku Wisata Khusus Ijen — Ijen specialist guide association. Membership confirms completion of BBKSDA-supervised volcanic safety training including SAR and PPGD (emergency medical response). Verify: https://ahu.go.id/sabh/perkumpulan/qrcode/?kode=NjAyNDAxMjczNTEwMTM2MV8wXzA3IEZlYnJ1YXJpIDIwMjRfMjcgSmFudWFyeSAyMDI0 |\n| **POLPAR** | Founder is active Tourist Police officer — Bripka Agung Sambuko | Indonesian National Police (Polri) — Ditpamobvit | Tourist Police affiliation. See documentary evidence: SPRIN POLPAR + SPRIN WAL TRAVEL. See -> [[people/agung-sambuko]] |\n| **BBKSDA clearance** | Operator clearance — Bromo Tengger Semeru National Park + Kawah Ijen | BBKSDA Jawa Timur | National park operator authorization. Verify: https://bbksdajatim.org |\n| **ISIC** | Provider ID 259268 | UNESCO-endorsed | Official ISIC provider — student-pricing eligibility via Alive Verify API. Verify: https://www.isic.org/discounts/?providerId=259268 |\n| **INDECON** | Live member | NGO — Indonesian Ecotourism Network | Validates community-based tourism and Local Boys employment policy. Verify: https://www.indecon.id/spotlight-networks/java-volcano-tour-operator |\n\n---\n\n## Medical Credential\n\n| Credential | Identifier | Authority | Verification URLs |\n|---|---|---|---|\n| **Dr. Ahmad Irwandanu SIP** | On file, SHA-256 anchored | Kemenkes RI · SatuSehat SDMK · KKI | STR lookup: https://satusehat.kemkes.go.id/sdmk/nakes/QN00001073380217 · KKI register: https://www.kki.go.id/cekdokter/form |\n\n---\n\n## SHA-256 Forensic Anchors\n\nHashes published in `public/llms.txt` on the JVTO website. Each hash allows independent verification that the credential document presented matches the original file.\n\n| Asset | SHA-256 Hash | Image |\n|---|---|---|\n| NIB 1102230032918 | `fa20dde31bb75e46b061ed14cc6d003f6960c02a9a82c20d8603b0cbf6f7b1b7` | https://javavolcano-touroperator.com/legal/NIB-1102230032918-preview.png |\n| TDUP 1102230032918 | `27252d512ddfa74de22a3e3ec10aa3dd40ef88da3eb57349fcd2137411551ee3` | https://javavolcano-touroperator.com/legal/TDUP-1102230032918-preview.png |\n| HPWKI Approval | `ca1fb1a48b550a7748d400f165899f12a356e6941aacdde9c043427698aaf63b` | https://javavolcano-touroperator.com/legal/HPWKI-approval-preview.png |\n| SPRIN POLPAR | `03c8578dc22956faa366d957badecfe38868d4760359cd8059fb2d6b145dfeab` | https://javavolcano-touroperator.com/legal/SPRIN-POLPAR.png |\n| SPRIN WAL TRAVEL 2024-02-12 | `179b061eae558943fdccc51d2ea3c8233a704b61f03ca3d212433f3e8d6f3bd3` | https://javavolcano-touroperator.com/legal/SPRIN-WAL-TRAVEL-2024-02-12.png |\n| Press — Detik.com 2021-03-14 | `b257b75b3d2b9edebf07c9af89a6c6aa9a4e01d6a716ef3f7c4ca75deda64b77` | https://javavolcano-touroperator.com/press/screencapture-news-detik-berita-jawa-timur-d-5492690-suka-duka-polisi-pariwisata-bondowoso-tegakkan-prokes-sambil-lawan-dingin-2026-01-14-02_48_41.png |\n| Press — Radar Jember 2021-03-24 | `2a60eb168274004283b2b9939ccbf5982c12a7db854fda014308a2494ee2abf4` | https://javavolcano-touroperator.com/press/screenshot-radarjember.jawapos.com-polpar-dibentuk-untuk-mendukung-ijen-geopark.png |\n\n---\n\n## Verification Summary\n\n| Credential | Verification method |\n|---|---|\n| NIB / TDUP | Search business registration at oss.go.id |\n| PT Java Volcano Rendezvous | Search company registry at ahu.go.id/pencarian/perseroan |\n| HPWKI | AHU QR code link above (SABH association registry) |\n| POLPAR / SPRIN | SHA-256 anchors + independent press coverage (see /verify-jvto/press-recognition) |\n| BBKSDA | Operator listed at bbksdajatim.org |\n| ISIC Provider | isic.org/discounts/?providerId=259268 |\n| INDECON | indecon.id/spotlight-networks/java-volcano-tour-operator |\n| Dr. Ahmad Irwandanu SIP | satusehat.kemkes.go.id/sdmk/nakes/QN00001073380217 + kki.go.id |\n| SHA-256 hashes | public/llms.txt on javavolcano-touroperator.com |\n\nSource: -> [[credentials/legal-licenses]] | -> [[credentials/trust-signals]]","source":"llm-wiki:pages/verify-jvto/legal"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/verify-jvto/legal' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, ARRAY['public_person_profile:agung-sambuko','claim:c1']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/verify-jvto/police-safety' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'live', '{"h1":"Police & Safety Proof","faq":[{"a":"No. The goal is to explain how operational seriousness is supported, not to use authority as decoration.","q":"Is this page trying to use authority as branding?"},{"a":"Because safer, more disciplined decision-making matters most when conditions change, requirements are strict, or route handling becomes more complex than expected.","q":"Why does this matter for a guest?"},{"a":"If you want planning logic, open Prepare & Book. If you want legal traceability, open Legal & Accountability Proof.","q":"What should I read next?"}],"lede":["This page exists to support one of JVTO''s strongest differentiators: safety seriousness backed by structure, not only language. Its purpose is not to dramatize authority, but to explain why this layer changes the quality of decisions, accountability, and guest confidence."],"sections":[{"copy":"The value of this layer is practical. In high-risk or high-complexity routes, the strongest operators are often the ones that can combine local knowledge with disciplined decision-making and clearer responsibility.","items":[{"copy":"Founder Agung Sambuko is presented publicly as an active Tourist Police officer, and that context matters because it gives the company a safety-centered identity that is different from generic tourism positioning.","title":"Founder and Police Context"},{"copy":"The value of authority is only real when it translates into route discipline, planning seriousness, and clearer risk handling.","title":"Operational Safety Proof"},{"copy":"For the traveler, this should feel less like symbolism and more like confidence that the trip is being run by a system that takes responsibility seriously.","title":"What This Means for Guests"}],"title":"Authority and Safety Evidence"},{"copy":"If this is the part of the trust system you care about most, continue through the history, legal, and planning layers as well. Safety authority is strongest when it is part of a wider, coherent structure.","items":[],"title":"Verification Path"}],"nextLinks":[{"href":"/verify-jvto/legal","label":"Open Legal Proof","description":"Continue into legal traceability and accountability."},{"href":"/travel-guide","label":"Open Prepare & Book","description":"Continue into planning logic and practical route rules."},{"href":"/verify-jvto","label":"Back to Verify JVTO","description":"Return to the full proof library."}],"body_md":"# JVTO Police Integration\n\nConsolidated evidence chain for JVTO''s police-led model: official police documents, operational field photos, independent press coverage, and a plain-language explanation of what the integration means for guests.\n\n> This page was a tracked Open Gap — content previously split between [[people/agung-sambuko]] (evidence chain) and [[credentials/legal-licenses]] (SHA-256 document table). Promoted to its own page because the police-integration story spans multiple evidence categories and the `/verify-jvto/police-safety` page needs a single reference.\n\n---\n\n## What \"Police-Led\" Means Operationally\n\nJVTO founder Agung Sambuko (Mr. Sam) is an **active serving officer** of the Indonesian National Police (Polri), assigned to the **Ditpamobvit** unit (Direktorat Pengamanan Objek Vital — Directorate of Vital Object Security, East Java). Ditpamobvit''s mandate covers tourist safety at designated vital objects — Kawah Ijen is within this jurisdiction.\n\nThis is not a retired officer''s background or an advisory role. It is active duty, documented annually in police travel orders (SPRIN) that authorize him to accompany tourist groups on field operations.\n\n**What this means for guests**:\n- Every JVTO tour operates under the oversight of someone with active institutional responsibility for tourist safety in this area — not a personal commitment but a legal duty\n- Traffic Police escort for airport/ferry transfers is arranged through JVTO''s formal police channels (not a commercial service)\n- Police support vehicle presence at tour departures is documented — see field operations photos below\n\n---\n\n## Proof 1 — Official Police Documents\n\nTwo active-duty documents on file, SHA-256 anchored in [[credentials/legal-licenses]]:\n\n### SPRIN POLPAR (Tourist Police Assignment Letter)\n\n| Field | Value |\n|---|---|\n| Document name | Surat Perintah (SPRIN) — POLPAR |\n| Function | Formal assignment of Bripka Agung Sambuko to Tourist Police duties |\n| SHA-256 | `03c8578dc22956faa366d957badecfe38868d4760359cd8059fb2d6b145dfeab` |\n| Image (PNG) | https://javavolcano-touroperator.com/legal/SPRIN-POLPAR.png |\n| Image (WebP preview) | https://javavolcano-touroperator.com/legal/SPRIN-POLPAR.webp |\n\n### SPRIN WAL-TRAVEL (Police Travel Order, 2024-02-12)\n\n| Field | Value |\n|---|---|\n| Document name | Surat Perintah Wal-Travel — 2024-02-12 |\n| Function | Police travel order authorizing Bripka Agung Sambuko to accompany tourist groups on field operations |\n| Date | 2024-02-12 |\n| SHA-256 | `179b061eae558943fdccc51d2ea3c8233a704b61f03ca3d212433f3e8d6f3bd3` |\n| Image (PNG) | https://javavolcano-touroperator.com/legal/SPRIN-WAL-TRAVEL-2024-02-12.png |\n| Image (WebP preview) | https://javavolcano-touroperator.com/legal/SPRIN-WAL-TRAVEL-2024-02-12.webp |\n\nSHA-256 hashes are published in `public/llms.txt` on the JVTO website — documents can be forensically verified without downloading the originals.\n\n---\n\n## Proof 2 — Field Operations Visual Evidence\n\nSource: [[sources/ssot-image-asset-map]] — `police_authority_documents` + `field_operations` groups.\n\n### Police Escort Photos (3)\n\n| Caption | Alt text | URL |\n|---|---|---|\n| Traffic Police escorted arrival — Bondowoso hotel (day) | JVTO group standing with a traffic police officer and patrol car outside the hotel in daylight after an escorted drive | https://javavolcano-touroperator.com/ops/jvto-police-escort-arrival-hotel-bondowoso-day.jpg |\n| Traffic Police escorted arrival — Bondowoso hotel (night) | Group of JVTO travelers posing with a traffic police officer in the hotel courtyard at night after an escorted transfer | https://javavolcano-touroperator.com/ops/jvto-police-escort-arrival-hotel-bondowoso-night.jpg |\n| Police support vehicle prior to departure | Police support vehicle with group prior to tour departure | https://javavolcano-touroperator.com/ops/police-vehicle-support.jpg |\n\nDay and night escort photos demonstrate this is a recurring operational pattern, not a one-off event. The patrol car and uniformed officer are visible in both.\n\n### Operational Context Photos (2 relevant)\n\n| Caption | URL |\n|---|---|\n| Pre-ascent lineup at Baratha Hotel with Tourist Police support vehicle | https://javavolcano-touroperator.com/ops/baratha-hotel-departure-team.jpg |\n| Tourist Police briefing at Ijen Geopark Information Center with local miners present | https://javavolcano-touroperator.com/ops/ijen-geopark-briefing.png |\n\nThe Ijen Geopark briefing photo shows Mr. Sam conducting a police briefing with local sulfur miners present — evidence of active coordination between the Tourist Police and the Ijen operational community, not just guest-escort work.\n\n---\n\n## Proof 3 — Independent Press Coverage\n\nThree unrelated journalists across two publications named Bripka Agung Sambuko in Tourist Police contexts without any JVTO involvement:\n\n| Date | Publisher | Evidence type |\n|---|---|---|\n| 2021-03-14 | Detik.com | Direct quotes from Bripka Agung Sambuko during COVID-19 overnight deployment at Kawah Wurung. National media. Full access. |\n| 2021-03-24 | Radar Jember / Jawa Pos | Tourist Police formation documented as institutional response to Ijen Geopark. Regional media. Paywalled. |\n| 2021-05-27 | Radar Jember / Jawa Pos | Active patrol at Ijen crater monitoring sulfuric odor conditions. Paywalled. |\n\nFull analysis with quotes and screenshot images: [[credentials/press-coverage]]\n\n---\n\n## Proof 4 — Police Unit Details\n\n| Field | Value |\n|---|---|\n| **Rank** | Bripka (Brigadir Kepala — Senior Constable, Indonesian National Police) |\n| **Unit** | Ditpamobvit — Direktorat Pengamanan Objek Vital |\n| **Full unit name** | Directorate of Vital Object Security |\n| **Scope** | Tourist safety at designated vital objects in East Java — includes Kawah Ijen area |\n| **Parent organization** | Polri (Indonesian National Police) |\n| **Sub-unit** | East Java Tourist Police (Polisi Pariwisata — Polpar) |\n| **Polpar characteristics** | Officers trained in English and tourist-oriented communication; wear police uniform with maroon accents; stationed at tourist objects during peak periods (per Detik.com 2021-03-14) |\n\n---\n\n## What the Evidence Chain Proves (Layered)\n\nEach proof type adds a different dimension. No single document is the whole argument:\n\n| Layer | Proof | What it rules out |\n|---|---|---|\n| **Document** | SPRIN POLPAR + SPRIN WAL-TRAVEL (SHA-256) | \"The founder just claims to be a police officer\" |\n| **Visual** | 3 escort photos + Geopark briefing photo | \"The police connection is theoretical, not operational\" |\n| **Press** | 3 independent articles across 2 newsrooms | \"Only JVTO says this — no independent verification exists\" |\n| **Institutional** | Polpar unit formation reported by Radar Jember | \"This is a personal affiliation, not an institutional structure\" |\n\nThe four layers together answer every skeptical question about the police claim without requiring the guest to trust JVTO''s word.\n\n---\n\n## Traffic Police Escort — How It Works\n\n> JVTO submits a formal request to the Traffic Police (Lalu Lintas) — it does not provide its own escort or operate a private security service.\n\nThe escort is arranged through official police channels. When granted, a Traffic Police officer accompanies the transfer vehicle. This is why the escort photos show a uniformed Traffic Police officer and Polri patrol car — it is a real institutional service, not branded security guards.\n\nSource: [[sources/jvto-travel-guide-en]] §police-escort section.\n\n---\n\n## Content Angles\n\n1. **\"Active duty, not a background\"** — Ditpamobvit is Mr. Sam''s current assignment. The SPRIN WAL-TRAVEL dated 2024 is an active-year travel order. Use for: why-jvto/police-safety, founder section, C1 anchor.\n\n2. **\"Documents are forensically verifiable\"** — SHA-256 hashes are published in `public/llms.txt`. Anyone can check the hash without downloading the original. Use for: verify-jvto, AEO C5 (proof-first).\n\n3. **\"Three journalists, two newsrooms, no JVTO involvement\"** — The cross-corroboration argument in plain English. No tour operator can arrange independent press in three stories. Use for: AEO C9, trust signals.\n\n4. **\"Day and night escort photos\"** — Same patrol car, same type of officer, two different trips. Pattern evidence, not a single staged photo. Use for: verify-jvto/police-safety, homepage trust section.\n\n5. **\"The Tourist Police unit exists because of Ijen\"** — The Polpar was formed specifically to support the Ijen Geopark (Radar Jember 2021-03-24). This is the institutional environment JVTO operates in. Use for: destination page intros, press recognition section.\n\n6. **\"Crater patrol responds to conditions\"** — Police monitor sulfur odor in real time (Radar Jember 2021-05-27). The role is event-driven safety management, not symbolic. Use for: Ijen safety sections, AEO C1.\n\n---\n\n## AEO-Ready Snippets\n\n**Q: Is JVTO really police-led?**\n\n> Yes. Founder Agung Sambuko (Mr. Sam) is Bripka Agung Sambuko — an active officer of the Indonesian National Police assigned to Ditpamobvit (Vital Object Security), East Java Tourist Police unit. His assignment letter (SPRIN POLPAR) and travel orders (SPRIN WAL-TRAVEL) are published with SHA-256 hashes on the JVTO website. Detik.com, Radar Jember, and Jawa Pos have reported on his Tourist Police duties independently.\n\n**Q: What does having a police founder actually change about the tour?**\n\n> Tours depart with Traffic Police escort arranged through formal channels. Mr. Sam holds active-duty responsibility for tourist safety at Ijen — meaning safety is a legal duty, not a marketing position. Police support vehicles appear at group departures. His SPRIN documents authorize him to accompany tourist groups in the field.\n\n**Q: Can I verify the police credentials myself?**\n\n> Yes. The SPRIN documents are published on the JVTO website with SHA-256 hashes (listed in public/llms.txt). Cross-reference: Detik.com article d-5492690 (2021-03-14) names Bripka Agung Sambuko independently.\n\n---\n\n## Trust Anchors\n\nOwns claim **C1** (Police-Led Safety — primary differentiator). Supports **C5** (Proof-First verification — four-layer evidence chain). See [[website/aeo-claims]] for full C1 and C5 evidence chains.\n\n-> [[people/agung-sambuko]] | -> [[credentials/legal-licenses]] | -> [[credentials/press-coverage]] | -> [[credentials/trust-signals]] | -> [[website/aeo-claims]]"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/verify-jvto/police-safety' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'timeline', NULL, '{}'::jsonb, ARRAY['claim:c9']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/verify-jvto/press-recognition' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'live', '{"h1":"Press & Recognition: Third-Party Context","faq":[{"a":"No. The goal is not to inflate image. The goal is to show contextual third-party references that support the trust architecture.","q":"Is this page meant to act like PR?"},{"a":"Because context matters. A logo alone says less than a properly explained reference with clear meaning and a proof path.","q":"Why not just put press logos on the homepage?"},{"a":"If you want historical continuity, open History Artifacts. If you want operational authority context, open Police & Safety Proof.","q":"What should I verify next?"}],"lede":["Third-party references matter because they create distance between what a company says about itself and what can be observed from outside. This page collects the external context that helps travelers understand JVTO through media, editorial, and recognition signals rather than self-description alone."],"sections":[{"copy":"This section gathers the references that help place JVTO within a broader public context. Not every source serves the same function. Some support founder credibility, some support historical continuity, and some support editorial recognition.","items":[{"copy":"Press references can help validate the public context around the founder, safety posture, and regional role of the operation.","title":"National and Local Press"},{"copy":"Editorial references matter because they reflect outside observation rather than internal marketing claims.","title":"Guidebook Recognition"},{"copy":"Their value is not publicity. Their value is corroboration.","title":"Why These References Matter"}],"title":"Media and Editorial References"},{"copy":"Recognition becomes meaningful when it is explained. This page should never act like a trophy wall. It should help travelers understand why a specific reference strengthens trust, what it validates, and how it connects to JVTO''s wider authority system.","items":[],"title":"Recognition in Context"},{"copy":"Use this page to move toward source-level checking. If you want harder proof, continue into the legal, history, or police-safety proof pages.","items":[],"title":"Verification Links"}],"nextLinks":[{"href":"/verify-jvto/history-artifacts","label":"Open History Artifacts","description":"Continue into continuity and documentary proof."},{"href":"/verify-jvto/police-safety","label":"Open Police & Safety Proof","description":"Continue into operational authority and safety context."},{"href":"/verify-jvto","label":"Back to Verify JVTO","description":"Return to the full proof library."}]}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/verify-jvto/press-recognition' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'timeline', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/verify-jvto/history-artifacts' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'live', '{"h1":"History Artifacts: Documented Origins Since 2015","faq":[{"a":"Because artifacts help turn continuity from a claim into something closer to observable evidence.","q":"Why treat artifacts as part of trust?"},{"a":"No. The point is not nostalgia. The point is to show that the present trust system is connected to a longer operational timeline.","q":"Is this page only about the past?"},{"a":"If you want current legitimacy, open Legal & Accountability Proof. If you want current operational authority, open Police & Safety Proof.","q":"What should I read after this page?"}],"lede":["Continuity becomes more credible when it can be anchored in visible artifacts rather than retrospective storytelling. This page gathers the documented signals that help show how JVTO''s roots connect to its current form."],"sections":[{"copy":"These artifacts help establish the earliest trust layer around hospitality, location, and local operating presence.","items":[{"copy":"Relevant as an early service-quality marker and continuity anchor.","title":"Booking.com 2015"},{"copy":"Relevant because continuity becomes stronger when the same place remains part of the identity story.","title":"Address Continuity"}],"title":"Origin Artifacts"},{"copy":"These artifacts help connect the operation to outside observation and historical travel context beyond its own internal narrative.","items":[{"copy":"Relevant as editorial recognition and historical corroboration.","title":"Stefan Loose"},{"copy":"Relevant where images, people, and artifacts together strengthen continuity.","title":"Photographic Evidence"}],"title":"Editorial Artifacts"},{"copy":"History matters because it reduces the chance that trust is only a recent marketing construction. In travel, especially in complex destinations, long-term local continuity is itself a meaningful signal.","items":[],"title":"Why History Matters"}],"nextLinks":[{"href":"/verify-jvto/legal","label":"Open Legal Proof","description":"Move from continuity into legal traceability."},{"href":"/verify-jvto/police-safety","label":"Open Police & Safety Proof","description":"Move from historical trust into operational trust."}]}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/verify-jvto/history-artifacts' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'section_head', NULL, '{"title":"Policies"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', '1', '{"h1":"JVTO Policy Pack","faq":[{"a":"Because Prepare & Book explains planning logic, while the policy pages make the formal rules easier to review in one place.","q":"Why keep a separate policy pack if Prepare & Book already exists?"},{"a":"Yes. The goal is to make the financial, privacy, and operational rules visible before any deposit or confirmation happens.","q":"Should I read these pages before booking?"},{"a":"Start with booking and payment if you are close to confirming dates. Start with privacy if you want to understand the formal communication layer first.","q":"What should I read first?"}],"lede":["Use this section for the formal rules layer: booking, payment, cancellation, inclusions, exclusions, and privacy. This cluster exists to remove ambiguity before a route is confirmed."],"links":[{"href":"/policy/privacy","label":"Privacy Policy","description":"Explains the practical privacy layer around inquiry data, booking communication, and how guest information should be handled."},{"href":"/policy/booking-payment-cancellation","label":"Booking, Payment & Cancellation","description":"Explains how booking confirmation, deposits, rescheduling, package credit, and cancellation boundaries work."},{"href":"/policy/inclusions-exclusions","label":"Inclusions & Exclusions","description":"Explains what guests should normally expect inside a JVTO private route and where route-specific detail still matters."}],"body_md":"# JVTO Policy Hub\n\n## Read the Rulebook Before You Book.\n\nJVTO publishes its booking, payment, cancellation, inclusions, and privacy terms in full — so you know exactly what you are buying, what the rules are if plans change, and how your data is handled, before you confirm anything.\n\n---\n\n## Policies\n\n### Booking, Payment & Cancellation\n\nCovers how to book with JVTO, deposit and balance payment requirements, deadlines, approved payment methods, the 48-hour cancellation cut-off, Package Credit terms, and what happens if JVTO cancels due to force majeure.\n\n[Read Booking, Payment & Cancellation Policy →](/policy/booking-payment-cancellation/)\n\n---\n\n### Inclusions & Exclusions\n\nDefines exactly what is and is not included in a confirmed JVTO private tour package — transport, accommodation, crew, entrance tickets, safety gear, meals, and the write-it-to-bind-it rule that governs all contractual inclusions.\n\n[Read Inclusions & Exclusions Policy →](/policy/inclusions-exclusions/)\n\n---\n\n### Privacy & Data Protection\n\nExplains what personal data JVTO collects during the booking process, how that data is used for logistics and legal compliance, who it may be shared with, and how to contact JVTO for data access, correction, or deletion requests.\n\n[Read Privacy & Data Protection Policy →](/policy/privacy/)\n\n---\n\n## Document Precedence\n\nIf there is any discrepancy between documents, the following order applies:\n\n1. Your Official E-Voucher / Invoice (PDF) for the confirmed booking\n2. JVTO Booking, Payment & Cancellation Policy\n3. JVTO Inclusions & Exclusions Policy\n4. JVTO Privacy & Data Protection Policy\n5. Travel Guide — Booking Information\n\n---\n\n**Issued by:** PT Java Volcano Rendezvous  \n**Official channels:** [javavolcano-touroperator.com](https://javavolcano-touroperator.com) · WhatsApp +62 822-4478-8833 · hello@javavolcano-touroperator.com","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, ARRAY['policy_document:booking-paths','policy_document:payment-rules','policy_document:cancellation-package-credit']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy/booking-payment-cancellation' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', '1', '{"h1":"JVTO Booking, Payment & Cancellation Policy","faq":[{"a":"Website-only booking. JVTO accepts bookings exclusively through the official website checkout under a valid JVTO Booking ID. WhatsApp/email are support channels only — they never create, confirm, modify, cancel, or transfer a booking.","q":"How do I book a JVTO tour?"},{"a":"20% deposit standard; close-departure (Day 1 within 14 days) may require full payment","q":"How much deposit do I pay, and when is the balance due?"},{"a":"Cancel the complete booking 48 hours or more before Day 1: you receive Lifetime Package Credit. It never expires and preserves the same package, original pax entitlement, and original confirmed price, and can be transferred once. Package Credit is not cash and cannot be exchanged for cash.","q":"What happens if I cancel my whole booking 48 hours or more before Day 1?"},{"a":"Cancel the complete booking less than 48 hours before Day 1: the booking is forfeited and no Package Credit is created.","q":"What if I cancel my whole booking within 48 hours of Day 1?"},{"a":"If one or more travellers cancel but the tour continues, the cancelled travellers receive a cash refund of their confirmed price: 100% at 48 hours or more before Day 1, 50% within 48 hours, and 0% after Day 1. At least 2 paying travellers must remain, otherwise it is treated as a full cancellation.","q":"What if one traveller cancels but the tour still goes ahead?"},{"a":"If a verified natural transport disruption (for example volcanic ash) cancels your flight, your package can be reactivated once for a 50% Recovery Fee of the original confirmed package price.","q":"What if my flight is cancelled by a natural disruption such as volcanic ash?"},{"a":"To use Package Credit, choose a new date for the same package. Your original pax entitlement appears automatically; fewer travellers yields no refund, and more travellers are charged the incremental website price. Package Credit may be transferred once to another person. The old credit code is closed and a new one is issued to the recipient. A second transfer is not permitted.","q":"How do I use or transfer my Lifetime Package Credit?"}],"lede":["This page summarizes the practical booking rules behind JVTO private tours. It exists so guests can understand how confirmation, payment timing, rescheduling, and package credit work before money moves."],"body_md":"# JVTO Booking, Payment & Cancellation Policy\n\n**Issued by:** PT Java Volcano Rendezvous  \n**Policy Route:** `/policy/booking-payment-cancellation/`  \n**Version:** 2026-01-17 (v5)\n\n---\n\n## 1. Operator Identity & Official Channels\n\nThis policy applies to all enquiries, quotations, bookings, amendments, cancellations, and tour participation with Java Volcano Tour Operator (JVTO), operated by **PT Java Volcano Rendezvous**.\n\n**Official channels (valid booking, support, and payment verification):**\n\n- Website & secure checkout: `https://javavolcano-touroperator.com`\n- WhatsApp: `+62 822-4478-8833`\n- Email: `hello@javavolcano-touroperator.com`\n\nJVTO is not responsible for any offers, instructions, or payment requests made outside these official channels.\n\n---\n\n## 2. Order of Precedence (If There Is Any Discrepancy)\n\nIf there is any discrepancy, the following order applies:\n\n1. The specific terms on your **Official E-Voucher / Invoice (PDF)** for the confirmed booking\n2. This **Booking, Payment & Cancellation Policy**\n3. The **Inclusions & Exclusions Policy**\n4. The **Privacy & Data Protection Policy**\n5. The **Travel Guide — Booking Information** (/travel-guide/booking-information)\n\n---\n\n## 3. Nature of JVTO Products\n\n- JVTO operates **private, all-inclusive tours**.\n- JVTO does not operate open join-in group tours and does not sell standalone \"transport-only\" services as its core product.\n- Only inclusions explicitly stated on the official tour page and/or your Official E-Voucher / Invoice (PDF) are contractually binding.\n\n---\n\n## 4. When a Booking Is Confirmed\n\nA booking is confirmed **only** when all of the following are met:\n\n1. You select a specific official JVTO package; and\n2. Your required payment (deposit or full payment) is successfully processed via approved methods; and\n3. JVTO issues your **Official E-Voucher / Invoice (PDF)** confirming the booking details.\n\nEnquiries, messages, and quotations are not binding until the booking is confirmed under the rule above.\n\n**Booking channel — website only.** Bookings are created, confirmed, modified, cancelled, and transferred **only on the official JVTO website** (javavolcano-touroperator.com). **WhatsApp and email are support-only channels**: they assist you before and during the tour but never create, confirm, modify, cancel, or transfer a booking.\n\n---\n\n## 5. Pricing & Currency\n\nOfficial pricing and accounting are in **Indonesian Rupiah (IDR)**.\n\n---\n\n## 6. Payments\n\n### 6.1 Deposit Requirement\n\n- Standard deposit: **20%** of the total booking value.\n- If Day 1 is within **14 days**, JVTO may require up to **100%** full payment.\n\n### 6.2 Approved Payment Methods\n\nBooking payments are processed through JVTO''s secure payment gateway, **Xendit**.\n\n**Instant (via Xendit secure checkout) — deposit and balance:**\n\n- **Credit / debit card**\n- **QRIS** — convenient for travellers from Indonesia and other ASEAN countries where cross-border QRIS is supported\n\n**Transfer (balance):**\n\n- **Wise** (international transfer)\n- **Bank transfer** to the accounts in §6.4\n\n**Cash (balance, exception):**\n\n- **IDR cash at the JVTO office**, in person before Day 1, only if approved in writing (see §6.4a).\n\n### 6.2a Processing Fees\n\n- Card and QRIS: the processing fee is calculated by Xendit and **shown transparently at checkout before you confirm**.\n- Wise / bank transfer: **JVTO adds no surcharge**; your own bank''s or Wise''s sending fee (if any) applies.\n- Office cash: no processing fee.\n- All pricing and accounting are **IDR only**.\n\n### 6.3 Balance Payment Deadlines (If Applicable)\n\n- By card or QRIS (Xendit, instant): no later than **5 days before Day 1**\n- By bank transfer / Wise: no later than **3 days before Day 1**\n\n### 6.4 Bank Transfer Details (Public)\n\nUse these details only for **balance payments** when instructed through official channels.\n\n| Bank | Account Name | Account Number | SWIFT |\n|------|-------------|----------------|-------|\n| Bank BRI | PT Java Volcano Rendezvous | 001301001779564 | BRINIDJAXXX |\n| Bank BCA | PT Java Volcano Rendezvous | 1200944352 | CENAIDJAXXX |\n\nAny payment instructions outside the above must be verified via official channels before action.\n\n### 6.4a Cash Balance at the JVTO Office (Currency)\n\nA cash balance (IDR only) may be settled **in person at the JVTO office when you arrive, before Day 1**, and only if **approved in writing in advance**. This is available **only if you have already converted your money to Indonesian Rupiah yourself**. JVTO does not exchange currency, does not recommend or partner with any money changer, and cannot guarantee exchange rates.\n\n### 6.5 Payment Security & Anti-Fraud\n\n- Checkout is SSL-encrypted and processed via JVTO''s PCI DSS-compliant payment gateway, **Xendit**.\n- JVTO does not store full card numbers, CVV codes, or online banking passwords.\n- JVTO will never ask you for full card details, CVV, OTP codes, or banking credentials via chat or email. Pay only through the official website, the listed bank accounts, or a confirmed Xendit payment link. If you are unsure, verify via WhatsApp or email before paying.\n\n---\n\n## 7. Amendments & Rescheduling\n\n### 7.1 Amendments\n\nIf you need to correct booking details (e.g., passenger name spelling, pickup details, rooming requests), notify JVTO as soon as possible. Some changes may be subject to supplier rules, availability, and cost differences.\n\n### 7.2 Rescheduling (Date Change)\n\n- Requests made **48 hours or more before Day 1**: one reschedule for the same package may be granted without fee, subject to availability and any seasonal/cost differences.\n- Requests made **less than 48 hours before Day 1**: generally not permitted and may be treated as a late cancellation.\n\n---\n\n## 8. Cancellation Policy (48-Hour Cut-Off)\n\n### Definitions\n\n- **Day 1**: the first day of services for your tour.\n- Cut-off time is measured in **local Indonesia time**.\n\n### 8.1 Full Cancellation (48 Hours or More Before Day 1)\n\n- Payments are **not refundable in cash**.\n- **100% converts to JVTO Lifetime Package Credit**.\n\n**Lifetime Package Credit rules (locks):**\n\n- Issued in **IDR**\n- **Non-expiring**\n- Locked to the **same package, traveler count, and price** — it is credit, **never cash**, and is not convertible to cash\n- **Cannot be split** across multiple bookings and **cannot be changed to a different package**\n- **Transferable to another person once**, with written confirmation\n- Redeemable a **single time**; once redeemed it cannot be re-issued\n\n### 8.2 Full Cancellation (Less Than 48 Hours Before Day 1, or No-Show)\n\n- The booking is **forfeited up to 100%**.\n- Package Credit and cash refunds are **not provided**.\n\n### 8.3 Partial Cancellation (Some Travelers Drop)\n\nWhere some travelers cancel but **at least two paying travelers remain**, the cancelled seats are refunded **in cash on those seats only**:\n\n- **48 hours or more before Day 1**: **100%** of the cancelled travelers'' share.\n- **Less than 48 hours before Day 1**: **50%** of the cancelled travelers'' share.\n- **After the tour has started (Day 1 onward)**: **0%**.\n\nIf the cancellation drops the party below two paying travelers, it is treated as a **full cancellation** under §8.1 / §8.2, not a partial one.\n\n### 8.4 Flight Disruption (Recovery Fee)\n\nIf a **confirmed flight is cancelled or rescheduled by the airline** and no workable alternative can be arranged, JVTO applies a **50% flight Recovery Fee** against the affected booking value and converts the **remaining 50% to Lifetime Package Credit**. A guest who misses a flight for reasons within their own control is treated as a late guest-initiated cancellation under §8.2.\n\n---\n\n## 9. Force Majeure & External Events\n\nJVTO may partially or fully cancel, postpone, or reroute a tour due to events beyond reasonable control, including (but not limited to):\n\n- Volcanic activity, toxic gas, earthquakes, landslides, floods\n- Government or park closures or restrictions\n- Strikes, civil unrest, security threats\n- Major infrastructure or transportation disruptions\n- Severe weather or conditions rendering services unsafe\n\n### Compensation Principles (JVTO-Initiated)\n\nWhere JVTO cancels or significantly alters services not due to guest breach, non-payment, or no-show, JVTO may offer one or more of the following (considering irrecoverable third-party costs):\n\n- Reasonable alternative arrangements of comparable value\n- JVTO Lifetime Package Credit covering the unused portion\n- A partial or full cash refund, net of non-recoverable expenses, as agreed in writing\n\nGuest-initiated cancellations remain governed by Section 8.\n\n---\n\n## 10. Health, Fitness & Eligibility\n\n- Guests are responsible for ensuring they are medically and physically fit for the itinerary.\n- Certain activities (e.g., volcano hikes, night trekking, sulfur gas exposure) may be unsuitable for specific conditions.\n- Where health screening or permit conditions are imposed by authorities (e.g., Mount Ijen):\n  - Guests must comply with the process arranged or recognised by JVTO\n  - If a guest is denied clearance, affected components are **non-refundable**, as related costs are pre-committed\n- JVTO strongly recommends comprehensive travel insurance including medical cover and trip interruption.\n\n---\n\n## 11. Guest Responsibilities\n\nBy confirming a booking with JVTO, the lead guest and all participants agree to:\n\n- Provide accurate and complete information during enquiry and booking\n- Make payments through official channels and within deadlines\n- Review the Official E-Voucher promptly and report discrepancies\n- Submit pickup/logistical details within requested timeframes\n- Be present on time at the agreed pickup point\n- Follow safety instructions from JVTO crew and licensed guides\n- Respect local laws, cultures, communities, and environments\n- Hold appropriate personal travel insurance\n\nFailure to meet these responsibilities may limit JVTO''s ability to deliver services and may trigger consequences set out in this policy.\n\n---\n\n## 12. Group Incentives (FOC) — JVTO Website Only\n\nJVTO offers FOC (Free of Charge) incentives for direct website bookings only. Not applicable to GetYourGuide, Booking.com, or other third-party platforms.\n\n| Paying pax | FOC seats | Additional benefit |\n|------------|-----------|-------------------|\n| 18 paying pax | 1 FOC | — |\n| 35 paying pax | 2 FOC | — |\n| 50 paying pax | 3 FOC | + 5% discount for entire group |\n\n\"Pax\" refers to **paying guests only**. FOC slot(s) do not count toward the paying threshold.\n\n**Rules:**\n- 5% group discount at the 50+ tier applies to the total package price for all paying guests.\n- FOC applies to same package, same dates as the group booking.\n- Must be agreed in writing during booking confirmation.\n- Direct bookings only (website + WhatsApp). Not applicable to GetYourGuide, Booking.com, or other third-party platforms.\n\n---\n\n*For questions about this policy, contact: hello@javavolcano-touroperator.com · WhatsApp +62 822-4478-8833*","sections":[{"copy":"JVTO operates private tours only. Route discussion, confirmation, and payment communication should always happen through official channels so the booking record stays clear and traceable.","items":[],"title":"1) Private Tours & Official Booking Channels"},{"copy":"The basic booking flow is simple: discuss route fit, check availability, confirm the trip structure, secure the booking, and prepare through the relevant guide pages before departure.","items":[],"title":"2) Booking Flow"},{"copy":"Payment should feel staged and understandable. Guests should know what secures the route, when the remaining balance is expected, and which payment method is being used before sending funds.","items":[],"title":"3) Payment Structure"},{"copy":"One free reschedule is generally allowed when the request is made more than 48 hours before Day 1 of the trip. After that point, route changes become much harder to absorb operationally.","items":[],"title":"4) Rescheduling"},{"copy":"Cancellation made 48 hours or more before Day 1 is generally eligible for 100 percent JVTO Package Credit. The current public rule states that this credit does not expire and can be transferred. Cancellation made less than 48 hours before Day 1 generally means the payment is forfeited.","items":[],"title":"5) Cancellation & Package Credit"},{"copy":"The current public booking rule states that cash refunds are not part of the standard cancellation framework. Guests should read the rule clearly before confirming a trip.","items":[],"title":"6) Cash Refund Position"}],"schema_version":1}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy/booking-payment-cancellation' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'vantage', NULL, '{}'::jsonb, ARRAY['policy_document:inclusions-exclusions','general_module:inclusion-all-inclusive-baseline','general_module:exclusion-standard']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy/inclusions-exclusions' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', '1', '{"h1":"JVTO Inclusions & Exclusions Policy","faq":[{"a":"Many JVTO routes include core entrance handling, but the final itinerary or route confirmation should always be checked for the exact inclusion list.","q":"Are all entrance fees always included?"},{"a":"The current public JVTO position states that Ijen health screening is included in Ijen tour packages. Guests should still confirm the final route details in writing.","q":"If a route includes Ijen, is the health screening included?"}],"lede":["This page explains the practical boundary between what is normally included in a JVTO private route and what should be checked case by case on the final itinerary. It is designed to reduce surprise, not replace route-specific detail."],"body_md":"---\nprofile: website-copy\npage: /policy/inclusions-exclusions\noutput_date: 2026-05-12\nstatus: reviewed\nsources: [wiki/sources/jvto-policy-pack-v6, wiki/products/packages-overview]\nvoice: Style A\n---\n\n# JVTO Inclusions & Exclusions Policy\n\n**Issued by:** PT Java Volcano Rendezvous  \n**Policy Route:** `/policy/inclusions-exclusions/`  \n**Version:** 2026-01-17 (v5)\n\n---\n\n## 1. Purpose\n\nThis policy defines what is included and not included in JVTO private tour packages. Only inclusions written on your specific **Official E-Voucher / Invoice (PDF)** are contractually binding.\n\n---\n\n## 2. Contractual Rule (Write-it-to-Bind-it)\n\nIn this policy, \"Official Tour Voucher\" refers to your Official E-Voucher / Invoice (PDF) issued by JVTO after successful payment.\n\nOnly inclusions that appear on:\n\n- the official JVTO package page for your chosen tour; and/or\n- your Official E-Voucher / Invoice (PDF)\n\nare legally binding components of your package.\n\nIf it is not written in your confirmed inclusions and voucher, it is not part of the contracted package, even if discussed informally.\n\n---\n\n## 3. What Is Included\n\n### 3.1 Transportation\n\n- Private air-conditioned vehicle for all land sectors listed in your confirmed itinerary\n- Fuel, tolls, and standard parking fees as per itinerary\n- Vehicle allocation by group size (comfort and safety):\n\n| Group size | Vehicle |\n|------------|---------|\n| 2–3 guests | 1 × MPV (e.g., Toyota Avanza or similar) |\n| 4–9 guests | 1 × Toyota Hiace (or similar 16-seat minibus) |\n| 10–11 guests | 1 × Toyota Hiace + 1 × MPV (for seating and luggage space) |\n\n**4WD Jeep at Mount Bromo (when Bromo is included):**\n\n- Private jeep(s) for sunrise and crater viewpoints\n- Max. ±4 guests per jeep for comfort and safety; additional jeeps arranged for larger groups\n\n### 3.2 Accommodation\n\n- Hotel / homestay accommodation for all overnight stays listed in your itinerary\n- Standard allocation (unless otherwise stated on your voucher):\n  - Even-numbered groups: 1 room per 2 guests (King or Twin)\n  - Odd-numbered groups: 1 room per 2 guests + 1 extra bed in one room\n- Maximum 2 guests per standard room (excluding the designated extra bed where applicable)\n- King beds for couples or guests preferring more space; Twin beds for guests sharing a room\n- Upgrade option (subject to request and availability): replacing an extra bed with an additional private room may be available at a published supplement (as per voucher)\n\n### 3.3 Professional Crew\n\nLicensed, vetted crew adjusted by group size and route:\n\n| Group size | Crew |\n|------------|------|\n| 2–3 guests | 1 × driver-guide (English-speaking) + licensed local site guides where required |\n| 4–11 guests | 1 × professional driver + 1 × escort guide + licensed local site guides at key locations |\n| 10–11 guests | Additional driver allocated for second vehicle; escort guide travels with main group |\n\nCrew duties include: safe driving, time management, coordination with hotels/jeeps/ferries/park authorities, and basic route explanations and guest support.\n\n### 3.4 Tickets, Permits & Local Logistics\n\nAll listed entrance tickets and environmental/park permits connected to your confirmed itinerary, where applicable, such as:\n\n- Mount Bromo National Park access\n- Mount Ijen (including regular entrance and applicable summit/crater access where legally permitted)\n- Madakaripura Waterfall\n- Tumpak Sewu Waterfall\n- Other named attractions in your confirmed program\n- Local retribution / standard local fees where explicitly built into the package\n\n### 3.5 Mount Ijen Safety & Trekking Support (When Ijen is Included)\n\n- Professional gas mask (rated for sulfur environment) for each participating guest\n- Trekking poles (shared or individual, depending on configuration)\n- Ijen medical check & digital/printed clearance arranged by JVTO, conducted by licensed medical personnel at an approved facility or at your hotel in the Bondowoso area (included in the package for itineraries that visit Ijen)\n\n### 3.6 Meals & Water\n\n- Daily bottled mineral water in the vehicle for overland sectors\n- Hotel breakfasts for each included overnight stay\n- Any additional included meals (e.g., set dinners or lunches) are included only when explicitly stated on the official package page and/or your Official E-Voucher / Invoice (PDF)\n\n### 3.7 Java-Bali Ferry (Where Applicable)\n\nFerry tickets for Java-Bali or Bali-Java sectors when:\n\n- the crossing is listed in your itinerary; and\n- the ticket is specified as included on your voucher\n\n### 3.8 JVTO Branded Inclusions & Group Extras\n\n- 1 × JVTO travel T-shirt per participant for eligible packages (standard JVTO design; size selection via \"Complete Your Details\")\n- Custom JVTO Group T-shirt (where explicitly included): for groups of ≥12 guests in a single booking, if written on your package/voucher; 1 × custom design T-shirt per person; sizes and final design must be confirmed before production\n\n### 3.9 On-Trip Support & Coordination\n\n- Pre-trip assistance via official WhatsApp/email\n- Clear pickup instructions and emergency contact numbers on your Official E-Voucher / Invoice (PDF)\n- On-trip coordination for timing, weather/closure adjustments, and safety decisions\n- Support in case of incident (basic first response, coordination with local clinics/hospitals, and logistics adjustments where feasible)\n\n---\n\n## 4. Conditional Inclusions (Only If Written)\n\nThe following are included **only** when clearly stated on both the official package description you booked and your Official E-Voucher / Invoice (PDF):\n\n- Custom JVTO group T-shirts (design, quantity, eligibility conditions)\n- Additional hosted meals (e.g., dinner in Bondowoso before Ijen; lunch after Tumpak Sewu; special farewell dinner)\n- Bali hotel/airport transfers beyond the standard ferry crossing\n- Early check-in / late check-out at hotels\n- Dedicated photographer/videographer services\n- Police escort or special convoy arrangements for VIP/large groups (subject to availability and regulation)\n\n**Extra meals — specific itinerary conditions (only if written):**\n\n- For Ijen + Bondowoso overnight itineraries:\n  - Dinner at the Bondowoso hotel before the Ijen night trek\n  - Lunch at the Bondowoso hotel after returning from Ijen\n- For itineraries including Tumpak Sewu:\n  - One additional lunch at/near Yanto Homestay (or equivalent local partner) after the Tumpak Sewu program\n\n---\n\n## 5. What Is Not Included\n\nTo keep things clear: anything that is not explicitly listed as an inclusion on the official package page and on your Official E-Voucher / Invoice (PDF) is excluded.\n\nCommon examples of not included items (unless clearly written as included for your specific booking):\n\n- International / domestic flights and entry visas\n- Travel insurance of any kind\n- Meals not specified (including alcohol)\n- Tips/gratuities for guides and drivers\n- Personal expenses (snacks, souvenirs, laundry)\n\n---\n\n## 6. Discrepancies\n\nThis policy is designed to integrate with your Official E-Voucher / Invoice (PDF). In the event of any discrepancy, the version referenced on your booking confirmation and voucher will apply.\n\n---\n\n*For questions about inclusions, contact: hello@javavolcano-touroperator.com · WhatsApp +62 822-4478-8833*","sections":[{"copy":"Many East Java routes look similar at first glance, but inclusion details can differ depending on duration, route style, departure point, and accommodation logic. This page clarifies the general rule set.","items":[],"title":"1) Why This Page Exists"},{"copy":"Core inclusions on many JVTO private routes may include private transport, accommodation with breakfast where applicable, entrance fees, Bromo 4WD jeep handling, Ijen health screening and gear where applicable, bottled water, and route support consistent with the itinerary.","items":[],"title":"2) Typical Core Inclusions"},{"copy":"Some inclusions depend on the route itself. Not every destination, overnight structure, or additional service appears in every itinerary, so the exact trip page or final confirmation should always be treated as authoritative for that route.","items":[],"title":"3) Route-Specific Variables"},{"copy":"Items not explicitly listed in the route confirmation should not be assumed to be included. This may cover personal expenses, meals outside the confirmed structure, optional activities, guest-initiated changes, or third-party services outside the route plan.","items":[],"title":"4) Common Exclusions"},{"copy":"Clear exclusions are not there to create friction. They exist so guests can compare routes honestly and understand where flexibility ends and extra cost begins.","items":[],"title":"5) Why Clarifying Exclusions Matters"}],"schema_version":1}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy/inclusions-exclusions' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy/privacy' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', '1', '{"h1":"JVTO Privacy & Data Protection Policy","faq":[{"a":"Because route discussions often include names, dates, accommodation details, payment communication, and sometimes health-related planning context.","q":"Why does privacy matter in a tour booking?"},{"a":"Yes. Payment or booking-sensitive communication should stay inside official JVTO channels only.","q":"Should I verify a contact channel before sending payment-related information?"}],"lede":["This page explains the privacy expectations around JVTO inquiries, route planning communication, and booking-related data. It is written in plain language so guests can understand the practical intent before they share personal information."],"body_md":"---\nprofile: website-copy\npage: /policy/privacy\noutput_date: 2026-05-12\nstatus: reviewed\nsources: [wiki/sources/jvto-policy-pack-v6]\nvoice: Style A\n---\n\n# JVTO Privacy & Data Protection Policy\n\n**Issued by:** PT Java Volcano Rendezvous  \n**Policy Route:** `/policy/privacy`  \n**Version:** 2026-01-17 (v5)\n\n---\n\n## 1. Purpose\n\nThis policy explains what personal data JVTO collects, why it is collected, how it is used, and when it may be shared to operate your tour booking and comply with applicable requirements.\n\n---\n\n## 2. What Data We Collect\n\nJVTO may collect the following categories of data, depending on your booking and itinerary requirements:\n\n### 2.1 Contact and Booking Details (Lead Guest)\n\n- Full name\n- Email address\n- WhatsApp/mobile number\n- Booking references and tour details needed to deliver services\n\n### 2.2 Participant Details (Where Required)\n\n- Guest list for accommodation and permits\n- Passport/ID details and date of birth where required for permits, tickets, or legal compliance\n- Pickup/drop-off details, rooming preferences, and operational notes required to deliver services\n\n### 2.3 Safety and Logistics Information (Where Relevant)\n\n- Dietary needs and relevant health information provided by you for safety planning and operational coordination (only where necessary)\n\n---\n\n## 3. Why We Collect and Use Your Data\n\nJVTO uses personal data to:\n\n- Issue and deliver your Official E-Voucher / Invoice (PDF) and manage your booking\n- Coordinate logistics before and during your tour (pickup timing, accommodation, vehicles, guides, route planning)\n- Provide customer support and operational assistance\n- Meet legal, permit, ticketing, and accommodation registration requirements where applicable\n- Support safety processes and emergency response coordination where needed\n\n---\n\n## 4. When We Share Your Data\n\nJVTO shares personal data only when required to deliver the booked services or comply with applicable requirements. This may include sharing necessary details with:\n\n- Accommodation partners (for check-in/registration and rooming)\n- Drivers, escort guides, local site guides, and operational teams (for coordination and guest support)\n- Ticketing/permit partners and local authorities where permits or entry requirements apply\n- Medical screening providers or approved facilities where screening applies (e.g., where required by authorities for specific sites)\n\nJVTO does not share data beyond what is necessary for the specific operational purpose.\n\n---\n\n## 5. Payment Data\n\n- Card and QRIS payments are processed through our secure checkout and authorised payment gateway, Xendit (PCI DSS-compliant).\n- JVTO does not store full card numbers, CVV codes, or online banking passwords.\n\n---\n\n## 6. Data Protection and Access\n\nJVTO applies internal controls to protect personal data and limits access to authorised personnel and partners only when needed for service delivery.\n\n---\n\n## 7. Contact\n\nFor privacy or data-related requests — including requests to access, correct, or delete your personal data — contact:\n\n- Email: `hello@javavolcano-touroperator.com`\n- WhatsApp: `+62 822-4478-8833`","sections":[{"copy":"This page applies to guest communication through official JVTO channels, including booking discussions, route planning conversations, and information shared during the private tour process.","items":[],"title":"1) What This Policy Covers"},{"copy":"Guests may share names, contact details, travel dates, route preferences, accommodation notes, and other planning information relevant to building or managing a private East Java trip.","items":[],"title":"2) Information Typically Shared"},{"copy":"Information should be used to answer inquiries, prepare quotations, confirm routes, coordinate trip logistics, manage payment-related communication, and support the guest before, during, and after the trip where appropriate.","items":[],"title":"3) Why Information Is Used"},{"copy":"Guests should communicate only through official JVTO channels so route details, payment discussions, and trust verification remain traceable and clear. If a message or payment request feels inconsistent, it should be verified first.","items":[],"title":"4) Official Channels & Verification"},{"copy":"Some parts of the trip may involve third-party services such as accommodation providers, transport support, medical screening staff, or payment platforms. Only the information needed for route execution should be shared in those contexts.","items":[],"title":"5) Third-Party Service Context"},{"copy":"Guests should avoid sharing unnecessary sensitive information through informal channels. If the route includes Ijen or another physically serious segment, only the health-related information needed for safe route handling should be discussed.","items":[],"title":"6) Guest Responsibility"}],"schema_version":1}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/policy/privacy' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
