INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Trust Bundle.","lede":["Single-page index of JVTO''s verifiable trust claims, evidence registry, and structured AEO/GEO signals. Compiled from the JVTO knowledge wiki.","Compiled 2026-07-07 from 9 claims, 18 evidence items, 50 entities."],"sections":[{"title":"Safety-Led Operations","body":"Safety-led planning. Clear boundaries. Plan B when conditions change."},{"title":"Private Tours (Execution Control)","body":"Private tours only. Your own vehicle. Your own pace (within safety limits). No mixed groups by default."},{"title":"All-Inclusive Clarity","body":"All-inclusive by default. Clear inclusions. Fewer surprise costs. Transparent pricing, written rules."},{"title":"Ijen Health-Screening Coordination","body":"A health certificate is mandatory for every Ijen guest — screening included and coordinated by JVTO. Real screening, clear rules."},{"title":"Proof-First Trust (Verification Layer)","body":"Proof you can verify — licenses, partners, press, and documented references. Trust stack, not slogans."},{"title":"Reviews Registry (Independent Validation)","body":"Reviews as a registry, not a quote wall. Check patterns across platforms."},{"title":"Our Team (Personality Economy + Operational Credibility)","body":"Meet the people behind your trip — with proof from reviews. Team profiles linked to real guest language."},{"title":"Partners as Context (HPWKI / INDECON / ISIC)","body":"Partners for context: competence, sustainability, and verification. Not logos — real functions."},{"title":"Press & Recognition (Third-Party Context)","body":"Press and recognition, explained with context. Third-party references you can evaluate."},{"title":"Want the underlying proof?","body":"The Verify hub holds the document evidence — NIB, TDUP, HPWKI, police credentials, and press coverage."}],"faq":[],"source":"scraped:https://help.javavolcano-touroperator.com/trust","scraped_at":"2026-07-28T00:00:00.000Z"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/trust' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/contact' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
