INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Contact Java Volcano Tour Operator","lede":["If you are comparing routes, checking fit, or asking about a custom plan, contact JVTO directly. You will be speaking with a real team, not a booking funnel disguised as support."],"channels":[{"href":"https://wa.me/6282244788833","label":"WhatsApp","value":"+62 822 4478 8833","description":"Fastest channel for route questions, availability checks, and early planning discussions. Official availability: 08:00-22:00 WIB."},{"href":"mailto:hello@javavolcano-touroperator.com","label":"Email","value":"hello@javavolcano-touroperator.com","description":"Best for written questions, multi-part inquiries, or guests who prefer to keep booking discussions documented in one place."},{"href":"https://www.google.com/maps/search/?api=1&query=Jl.+Khairil+Anwar+No.102+A,+Badean,+Bondowoso,+East+Java+68214,+Indonesia","label":"Office","value":"Jl. Khairil Anwar No.102 A, Badean, Bondowoso, East Java 68214","description":"Bondowoso headquarters of PT Java Volcano Rendezvous. Useful as a trust signal and for guests who want the operator identity to stay fully visible before payment."}],"sections":[{"copy":"Use this page when you need direct help choosing the right itinerary, checking availability, or clarifying route logic.","items":[{"copy":"Ask when you are unsure whether Bromo, Ijen, waterfalls, or a longer overland route actually matches your timing and energy.","title":"Route Fit Questions"},{"copy":"Ask when you already know the route logic you want and need to check whether the dates can be handled cleanly.","title":"Availability Questions"},{"copy":"Ask when your route needs a non-standard sequence, different start and end points, or a more tailored planning conversation.","title":"Custom Planning Questions"}],"title":"Talk to a Real Team Member"},{"copy":"Good inquiries are easier to answer well. The team can help faster when the route basics are already clear.","items":[{"copy":"Decide whether you are planning from Surabaya or Bali first. That choice changes the route logic more than many first-time guests expect.","title":"Know Your Starting Point"},{"copy":"A route only makes sense when it fits the time window honestly. Short trips and multi-day overland journeys are not interchangeable.","title":"Know Your Available Days"},{"copy":"If Ijen is on your shortlist, read the health screening page before you ask for dates so the conversation starts from realistic expectations.","title":"Know Whether Ijen Is Included"}],"title":"Before You Contact Us"},{"copy":"A short, practical inquiry is enough. The goal is simply to give the team enough context to guide you without guesswork.","items":[{"copy":"Share the dates or at least the month and flexibility range you are considering.","title":"Travel Window"},{"copy":"Tell the team whether you are starting from Surabaya or Bali, and whether you need to finish in a different city or island.","title":"Start and End Point"},{"copy":"Share how many people are traveling and whether your priority is volcanoes, waterfalls, route comfort, or a broader East Java discovery.","title":"Group Size and Priorities"}],"title":"What To Include In Your First Message"},{"copy":"JVTO operates private tours only. Communication and booking should stay on official channels so route, payment, and expectations remain clear.","items":[{"copy":"If any payment instruction feels inconsistent, pause and verify it through JVTO''s official WhatsApp or official email first.","title":"Verify Before Payment"},{"copy":"Use written communication to confirm what route is being discussed, what is included, and which practical rules apply.","title":"Keep Route Logic Visible"},{"copy":"JVTO''s legal entity is PT Java Volcano Rendezvous, with NIB and TDUP 1102230032918 and a Bondowoso office base.","title":"Trust the Official Identity"}],"title":"Official Channel Rules"}],"inquiryTemplates":[{"copy":"Best for guests who already know the likely package and want to move quickly into availability and quote logic.","title":"I Know My Route, I Need Date and Price Fit","prompt":"Hello JVTO, I am considering [route name]. We are [group size] people, likely starting from [Surabaya/Bali], and looking at [date range]. Could you confirm availability and the best private option?","emailHref":"mailto:hello@javavolcano-touroperator.com?subject=JVTO%20route%20availability%20inquiry&body=Hello%20JVTO%2C%20I%20am%20considering%20%5Broute%20name%5D.%20We%20are%20%5Bgroup%20size%5D%20people%2C%20likely%20starting%20from%20%5BSurabaya%2FBali%5D%2C%20and%20looking%20at%20%5Bdate%20range%5D.%20Could%20you%20confirm%20availability%20and%20the%20best%20private%20option%3F","whatsappHref":"https://wa.me/6282244788833?text=Hello%20JVTO%2C%20I%20am%20considering%20%5Broute%20name%5D.%20We%20are%20%5Bgroup%20size%5D%20people%2C%20likely%20starting%20from%20%5BSurabaya%2FBali%5D%2C%20and%20looking%20at%20%5Bdate%20range%5D.%20Could%20you%20confirm%20availability%20and%20the%20best%20private%20option%3F"},{"copy":"Best for guests who have the time window but still need help choosing the route shape honestly.","title":"I Need Help Choosing Between Bromo, Ijen, or a Combo","prompt":"Hello JVTO, we have around [1/2/3/5] days and are deciding between Bromo, Ijen, or a combo route. We start from [Surabaya/Bali] and our priority is [volcanoes / comfort / variety / overland]. What route would you recommend?","emailHref":"mailto:hello@javavolcano-touroperator.com?subject=JVTO%20route%20selection%20help&body=Hello%20JVTO%2C%20we%20have%20around%20%5B1%2F2%2F3%2F5%5D%20days%20and%20are%20deciding%20between%20Bromo%2C%20Ijen%2C%20or%20a%20combo%20route.%20We%20start%20from%20%5BSurabaya%2FBali%5D%20and%20our%20priority%20is%20%5Bvolcanoes%20%2F%20comfort%20%2F%20variety%20%2F%20overland%5D.%20What%20route%20would%20you%20recommend%3F","whatsappHref":"https://wa.me/6282244788833?text=Hello%20JVTO%2C%20we%20have%20around%20%5B1%2F2%2F3%2F5%5D%20days%20and%20are%20deciding%20between%20Bromo%2C%20Ijen%2C%20or%20a%20combo%20route.%20We%20start%20from%20%5BSurabaya%2FBali%5D%20and%20our%20priority%20is%20%5Bvolcanoes%20%2F%20comfort%20%2F%20variety%20%2F%20overland%5D.%20What%20route%20would%20you%20recommend%3F"},{"copy":"Best for guests who are interested in Ijen but want to understand screening, route seriousness, and whether the route is realistic first.","title":"I Want an Ijen Route and Need Screening Clarity","prompt":"Hello JVTO, we are interested in an Ijen route. Before choosing dates, could you clarify the health screening process, where it happens, and which private route you recommend for [group size] people starting from [Surabaya/Bali]?","emailHref":"mailto:hello@javavolcano-touroperator.com?subject=JVTO%20Ijen%20screening%20inquiry&body=Hello%20JVTO%2C%20we%20are%20interested%20in%20an%20Ijen%20route.%20Before%20choosing%20dates%2C%20could%20you%20clarify%20the%20health%20screening%20process%2C%20where%20it%20happens%2C%20and%20which%20private%20route%20you%20recommend%20for%20%5Bgroup%20size%5D%20people%20starting%20from%20%5BSurabaya%2FBali%5D%3F","whatsappHref":"https://wa.me/6282244788833?text=Hello%20JVTO%2C%20we%20are%20interested%20in%20an%20Ijen%20route.%20Before%20choosing%20dates%2C%20could%20you%20clarify%20the%20health%20screening%20process%2C%20where%20it%20happens%2C%20and%20which%20private%20route%20you%20recommend%20for%20%5Bgroup%20size%5D%20people%20starting%20from%20%5BSurabaya%2FBali%5D%3F"}]}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/contact' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'section_head', NULL, '{"title":"Insights"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/blog' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'design-system', '{"h1":"JVTO Blog","body_md":"# JVTO Blog\n\n## Hub Intro\n\nEast Java is not a destination you improvise. Crater access rules change. Volcanic gas levels shift overnight. A waterfall canyon that was passable last week may be running too high today.\n\nThis blog covers what we actually know from the ground: current conditions, safety protocols, packing guidance, route facts, and the regulations that govern each destination we operate. Mr. Sam''s team — KTA-credentialed guides and drivers based in Bondowoso — is on-site year-round. What they learn, we publish here.\n\nNo sponsored content. No tour-aggregator rewrites. Just operational information you can act on.\n\n---\n\n## Topic Pillars\n\n### 1. Kawah Ijen — Conditions, Access Rules & the Blue Fire\n\nBlue Fire is a natural phenomenon driven by volcanic gas combustion. It is not guaranteed on any single visit — weather, gas levels, and BBKSDA access conditions all affect what you see. We cover: how BBKSDA SE.1658/KSA.9/2024 governs crater-zone access, what a valid QR code means and why it matters, the monthly closure schedule (first Friday of every month), and how health-certificate screening coordination works for every guest under BBKSDA SE.1658/KSA.9/2024.\n\n### 2. Mount Bromo — Sunrise, the Tengger Caldera & the Yadnya Kasada Festival\n\nBromo''s pre-dawn slot means arriving at the viewpoint by 03:30–04:00. What looks simple on paper involves a jeep convoy across the Sea of Sand in the dark, temperatures of 5–15°C, and timing around the Yadnya Kasada festival (lunar calendar, access may be restricted) when it falls. We document the full route, the jeep sequence, and how JVTO''s Plan-B SOP works when festival crowds or closures force a route change.\n\n### 3. Madakaripura — The Waterfall Canyon That Gets You Wet\n\nMadakaripura is the tallest waterfall in Java. The approach involves wading through a stream, navigating narrow canyon passages, and standing under water. Waterproof bags are not optional. We cover: what to pack, how the canyon entry works, what helmets are provided (by local site management, not JVTO), and how to read the water levels before committing to the descent.\n\n### 4. Tumpak Sewu — Steep Trail, Fixed Ropes & the Canyon Floor\n\nThe descent to the Tumpak Sewu canyon floor involves steep, wet sections with fixed rope handholds. Water shoes with grip matter here. We cover: trail conditions by season, fitness requirements, what the canyon floor looks like at different water volumes, and the practical difference between the viewpoint visit and the full canyon descent.\n\n### 5. Packing Guides, Health Checks & What to Declare at Booking\n\nAcross all East Java volcano tours, the recurring preparation mistakes are the same: wrong footwear, no warm layer for pre-dawn starts, dietary requirements not declared at booking. We publish destination-specific packing lists, explain how health-screening coordination works on Ijen routes (for every guest before Kawah Ijen crater entry (BBKSDA SE.1658/KSA.9/2024)), and outline what dietary needs (vegetarian, vegan, gluten-free) must be confirmed before Day 1.\n\n---\n\n> **Production note**: Individual post copy is not in scope — no posts exist in the wiki yet. The sections above define the five content pillars for the blog hub page. Each pillar maps to a destination or operational topic already documented in the JVTO wiki. Post-level copy should be generated per pillar using Workflow 5 (compilation profile) once post briefs are defined.","schema_version":"design-system"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/blog' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, ARRAY['claim:c5','policy_document:anti-fraud']::text[], '{}'::text[], false FROM pages p WHERE p.route = '/blog/why-not-unlicensed-ijen-operator' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/blog/2026-06-11-kawah-ijen-guide' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'live', '{"h1":"Your Complete Kawah Ijen Guide: Blue Fire, Health & Safety","lede":["Kawah Ijen is an active stratovolcano at 2,386m, home to the world''s highest-volume acidic crater lake and a pre-dawn blue fire phenomenon that draws thousands of hikers every year. Seven documented tourist incidents at Ijen between 2015 and 2026 — including four fatalities — mean the preparation you do before the trailhead matters as much as the gear you carry.","This guide covers what to expect on the hike, how the health certificate process works, what the restricted zones are, and why the choice of operator changes your risk profile."],"sections":[{"title":"What Is the Blue Fire — and Why It''s Not Guaranteed","body":"The blue fire at Kawah Ijen is a natural phenomenon. Ignited sulfuric gases vent from the crater floor and combust on contact with oxygen, producing an electric-blue flame visible only in darkness. When conditions align, it is extraordinary.\n\nBut it is subject to weather and gas activity . Thick fog, rain, or elevated gas readings can make the crater inaccessible or the fire invisible. No reputable operator can guarantee you will see it. JVTO plans around the optimal departure window (midnight from Paltuding), but the outcome is the volcano''s to decide.\n\nWhat you can count on: the hike itself, the turquoise acidic crater lake, sunrise from the rim at 2,386m, and the sulfur miners who have worked this crater for over a century."},{"title":"The Hike: What You''re Actually Signing Up For","body":"The trail is not technical climbing. It is steep, uneven, and done in darkness, cold, and volcanic gas. Gas masks and headlamps are standard JVTO inclusions — not optional upgrades."},{"title":"Health Certificates: The Regulatory Reality","body":"Since 2024, BBKSDA East Java (Surat Edaran SE.1658/KSA.9/2024) has established conditions under which crater access requires a recent local health certificate. When those conditions apply, a valid QR code is the entry requirement: no certificate, no crater access .\n\nJVTO coordinates the health-screening workflow through the Ijen Digital Health Security System (health.mountijen.com). The process before your hike:\n\nThe data above is not bureaucratic overhead. Of the four fatal incidents at Kawah Ijen since 2015, two were fitness-related: a 68-year-old who died from exhaustion and respiratory distress, and a 64-year-old cardiac arrest at the mid-trail rest post. The screening is built to identify exactly these risk profiles before the trailhead — not after.\n\nIf a guest is assessed unfit, the climb is cancelled for that individual. This is a regulatory outcome, not operator discretion."},{"title":"The Sulfur Miners","body":"Approximately 200–300 miners work the Kawah Ijen crater, carrying 70–90 kg sulfur loads twice daily in direct SO₂ exposure. They share the trail with tourists and have been doing so for over a century.\n\nJVTO briefs every guest before departure:\n\nThe briefing is the minimum courtesy. These are working people, not scenery."},{"title":"Why the Operator Choice Matters","body":"JVTO''s founder, Agung \"Mr. Sam\" Sambuko, is an active Tourist Police officer (Ditpamobvit) — the only East Java operator with this credential. The company holds NIB 1102230032918, TDUP, HPWKI membership, POLPAR, and BBKSDA operator clearance. All are independently verifiable at /verify-jvto .\n\nEvery JVTO Ijen tour is:\n\nThe company has operated at Kawah Ijen since 2015. Across Trustpilot (4.8/5, 51 reviews), Google Maps (4.9/5, 123 reviews), and TripAdvisor (4.95/5, 21 reviews), 195 independent reviews reflect a decade of operations at this specific volcano."},{"title":"Plan Your Ijen Trip","body":"Browse Ijen packages from Surabaya or Bali at /tours . For the full credential record — licenses, police credentials, medical screening evidence — visit /verify-jvto . Health screening specifics: /travel-guide/ijen-health-screening ."}],"faq":[],"source":"scraped:https://help.javavolcano-touroperator.com/blog/2026-06-11-kawah-ijen-guide","scraped_at":"2026-07-28T00:00:00.000Z"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/blog/2026-06-11-kawah-ijen-guide' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 1, 'rich_text', NULL, '{}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/blog/2026-06-11-ijen-medical-checkup-requirement' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', 'live', '{"h1":"Why Ijen Trekking Requires a Medical Checkup — And What Actually Happens","lede":["Kawah Ijen is one of the most extraordinary hikes in Southeast Asia. A 3 km night ascent to a 2,386 m crater rim, a pre-dawn descent toward the world''s largest acidic lake, and — if conditions allow — the blue fire phenomenon that draws travelers from every continent.","It is also a hike with a documented history of cardiac emergencies.","Since 2015, seven tourist incidents have been recorded at Ijen — including four fatalities. Half of those deaths were fitness-related: a 68-year-old who collapsed from exhaustion and respiratory distress, a 64-year-old who suffered a heart attack at Post 3. These are not freak accidents. They are predictable outcomes on a steep, high-altitude, sulfurous trail for guests whose baseline health was never assessed before the climb.","That is precisely why BBKSDA East Java — the government authority controlling all access to Kawah Ijen — issued Surat Edaran SE.1658/KSA.9/2024 : the regulation under which every trekker must present a local health certificate before entering the crater zone."],"sections":[{"title":"Who Requires the Health Certificate — BBKSDA, Not JVTO","body":"This is the first thing to understand: JVTO does not unilaterally impose a health screening requirement. The rule originates with BBKSDA East Java (Balai Besar Konservasi Sumber Daya Alam), the Nature Conservation Agency that manages the Kawah Ijen nature reserve.\n\nUnder SE.1658/KSA.9/2024, BBKSDA requires every visitor to carry a verifiable health certificate. No valid certificate = no crater access. The gate has a QR reader.\n\nJVTO''s role is coordination: JVTO arranges the mandatory screening workflow so guests arrive at Paltuding ready to enter. The session is included in the package price and scheduled before the night departure. It is a service, not an arbitrary gatekeeping policy.\n\nYou can verify the BBKSDA ticket terms directly at tiket.bbksdajatim.org — the health certificate requirement is stated in the public-facing crater access terms."},{"title":"What Gets Measured in the Screening","body":"The Ijen health screening runs through the Ijen Digital Health Security System (health.mountijen.com). It takes approximately 15–20 minutes and measures four data points:\n\nIf all four metrics are within safe parameters, the doctor issues a surat sehat (health certificate): a QR-coded document linked to the licensed physician''s identity. The QR code is scanned by the BBKSDA gate officer at Paltuding. The certificate cannot be forged — it carries the doctor''s SIP number and is tied to a government-verifiable registry."},{"title":"Who Issues the Certificate — Dr. Ahmad Irwandanu","body":"The licensed physician coordinating Ijen health certificates through JVTO is Dr. Ahmad Irwandanu , based in Bondowoso, East Java.\n\nHis credentials are publicly verifiable — no trust required:\n\nThis matters because the certificate he issues carries real legal weight. An illegitimate practitioner''s QR code would fail at the BBKSDA gate reader. The auditable credential chain — KKI registry → Kemenkes SatuSehat → SIP number → QR certificate → BBKSDA gate scan — is what makes the system tamper-resistant.\n\nThe screening takes place at one of two partner facilities:\n\nFor guests on JVTO packages, the session is coordinated to fit the pre-departure timeline."},{"title":"What Happens If You Don''t Pass","body":"If the screening assessment finds you are not fit for the climb, the trek is cancelled for that individual — not for the group.\n\nThat distinction matters. If a couple is traveling together and one guest passes while the other does not, the group does not have to abandon the hike. The guest assessed as unfit can wait at base camp or the designated safe zone while the rest of the group continues.\n\nThe cost of the screening session itself is non-refundable. The assessment was performed, the clinical time was spent. This applies across all Ijen health-certificate providers — it is not a JVTO-specific policy.\n\nThis outcome is governed by regulatory protocol, not operator discretion. JVTO has no mechanism to override a BBKSDA access rule or a doctor''s fitness assessment."},{"title":"Why This Exists: The Incident Data","body":"Between 2015 and 2026, documented Ijen incidents include:\n\nBoth deaths occurred in the fitness-risk category that health screening specifically targets: SpO2, blood pressure, cardiovascular baseline. A basic vitals assessment before the climb would have flagged the elevated risk.\n\nThe other incidents on record — the 2024 cliff fall that led to Hutan Mati zone closure, two motorcycle accidents on the Sengkan Gandrung descent road in 2025, and the 2026 SAR operation for a lost hiker — fall into different risk categories: terrain, navigation, and transport. That is why JVTO also provides certified guides, professional drivers with certified vehicles, and route supervision alongside the health coordination.\n\nThe health certificate is one layer of a multi-layer safety system."},{"title":"What This Looks Like in Practice (On a JVTO Package)","body":"For guests on an Ijen-relevant JVTO package, the screening workflow runs as follows:\n\nThe session adds roughly 15–20 minutes to pre-hike logistics. JVTO builds this into the departure timeline so it does not affect the midnight climb window targeting the blue-fire viewing slot.\n\nOf JVTO''s 16 tour packages, 12 are Ijen-relevant and include this mandatory health-screening coordination workflow — a certificate is required for every guest before crater entry. Only the three non-Ijen packages (Bromo day trips and Taman Safari) operate outside this protocol."},{"title":"The Short Version","body":"A BBKSDA-mandated local health certificate is required for every guest before Ijen crater access. JVTO coordinates the certification workflow through licensed physician Dr. Ahmad Irwandanu — credentials publicly verifiable via Kemenkes SatuSehat and KKI. The screening measures four vitals, takes 15–20 minutes, and issues a QR-verified certificate. Guests who do not pass cannot enter the crater zone — individual cancellation, not group cancellation. The screening cost is non-refundable.\n\nThis is not a bureaucratic formality. It is the mechanism designed to catch the fitness risks that have historically ended in fatalities on this trail.\n\nSources: [[people/dr-ahmad-irwandanu]] · [[destinations/kawah-ijen]] · [[products/packages-overview]] · [[credentials/trust-signals]]"}],"faq":[],"source":"scraped:https://help.javavolcano-touroperator.com/blog/2026-06-11-ijen-medical-checkup-requirement","scraped_at":"2026-07-28T00:00:00.000Z"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/blog/2026-06-11-ijen-medical-checkup-requirement' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
