INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 3, 'page_content', '1', '{"h1":"Local field crew behind JVTO''s private volcano operations.","lede":"JVTO''s trust layer is not only documents. It is also the people running night pickups, mountain approaches, health-screening logistics, and guest support across East Java.","source":"JVTO_SSOT_v4_0_CLEAN.json crew_registry","members":[{"id":"dika","url":"https://javavolcano-touroperator.com/team/dika","name":"Dika","role":"Driver","evidence":[],"position":1,"knowsAbout":["Friendly & fun","Safety-first","Great logistics","Knowledgeable guide"],"description":"Dika is part of JVTO''s East Java field team, focused on Friendly & fun, Safety-first, Great logistics."},{"id":"fredi","url":"https://javavolcano-touroperator.com/team/fredi","name":"Fredi","role":"Driver","evidence":[{"claim":"Reliability","quote":"Always on time no matter what time of the day. Exceptional driving skills.","source_author":"Pooja Prakash","source_platform":"Google Reviews"}],"position":2,"knowsAbout":["Friendly & fun","Great logistics","Always on time","Safety-first","Knowledgeable guide","Great photos"],"description":"Experienced Tour Driver committed to making your travels memorable. I combine safe driving skills with a friendly, helpful attitude to provide a stress-free experience. Whether it''s a short trip or a long tour, I prioritize guest comfort and reliable service at all times."},{"id":"holili","url":"https://javavolcano-touroperator.com/team/holili","name":"Holili","role":"Driver","evidence":[],"position":3,"knowsAbout":["Friendly & fun","Safety-first","Great logistics"],"description":"I am a Java Volcano driver who dedicates myself to serving all Java Volcano customers wholeheartedly."},{"id":"joyo","url":"https://javavolcano-touroperator.com/team/joyo","name":"Joyo","role":"Driver","evidence":[],"position":4,"knowsAbout":["Friendly & fun","Safety-first","Great logistics","Knowledgeable guide"],"description":"I''m a professional driver who combines speed with precision and care. I drive fast, but always cleanly, smoothly, and safely. My vehicle is kept in impeccable condition inside and out; cleanliness and comfort are non-negotiable for every single ride. Clients frequently tell me I''m their number one choice, \"Customer Number 1\", because they know they''ll get to their destination quickly without ever feeling rushed or unsafe. I take pride in being punctual, reliable, and genuinely attentive to what each passenger needs, whether it''s a daily commute, an important business trip, airport transfer, or a special occasion."},{"id":"pras","url":"https://javavolcano-touroperator.com/team/pras","name":"Pras","role":"Driver","evidence":[{"claim":"Language Skills","quote":"Excellent English... made interactions seamless. Best guide I''ve ever had.","source_author":"Filwyn Ma","source_platform":"Google Reviews"},{"claim":"Safe Driving","quote":"Driving technique is superb... responsible and trustworthy.","source_author":"Ki Wing Chu","source_platform":"Google Reviews"}],"position":5,"knowsAbout":["Friendly & fun","Great logistics","Safety-first","Knowledgeable guide","Always on time","Great photos"],"description":"Pras is part of JVTO''s East Java field team, focused on Friendly & fun, Great logistics, Safety-first."},{"id":"yandi","url":"https://javavolcano-touroperator.com/team/yandi","name":"Yandi","role":"Driver","evidence":[],"position":6,"knowsAbout":["Friendly & fun","Great logistics","Knowledgeable guide","Always on time","Safety-first","Great photos"],"description":"Love meeting people from different backgrounds and making every trip feel easy and enjoyable. I like to have new friend especially from overseas because can share about our unique culture. always make sure safety during the trip and make unforgettable moment along a journey."},{"id":"yusuf","url":"https://javavolcano-touroperator.com/team/yusuf","name":"Yusuf","role":"Driver","evidence":[],"position":7,"knowsAbout":["Friendly & fun","Great photos","Great logistics"],"description":"Yusuf is part of JVTO''s East Java field team, focused on Friendly & fun, Great photos, Great logistics."},{"id":"anjas","url":"https://javavolcano-touroperator.com/team/anjas","name":"Anjas","role":"Guide","evidence":[{"claim":"Creative","quote":"Creative at taking fun photos... Anjas was the highlight for the trip.","source_author":"Wang Zhe","source_platform":"Google Reviews"}],"position":8,"knowsAbout":["Friendly & fun","Great logistics","Great photos","Knowledgeable guide","Safety-first","Always on time"],"description":"m a chill guy and nerdy enough to talk about brainrote meme. love playing games and listening to any kind of music. let me show you around how beautiful east java is."},{"id":"boy","url":"https://javavolcano-touroperator.com/team/boy","name":"Boy (Ahboy)","role":"Guide","evidence":[{"claim":"Knowledge","quote":"Incredibly knowledgeable and went out of his way to make sure everything we needed was sorted.","source_author":"Jason Li","source_platform":"Trustpilot"}],"position":9,"knowsAbout":["Friendly & fun","Knowledgeable guide","Safety-first","Great logistics","Always on time","Great photos"],"description":"I am a local resident who enjoys welcoming visitors and sharing stories about this area. I''m happy to help travelers explore the natural beauty, local culture, and unique experiences so they feel comfortable and truly enjoy their visit."},{"id":"fauzi","url":"https://javavolcano-touroperator.com/team/fauzi","name":"Fauzi","role":"Guide","evidence":[],"position":10,"knowsAbout":["Friendly & fun","Knowledgeable guide","Great logistics","Great photos","Safety-first"],"description":"I''m a friendly guide who loves taking photos for guests and quickly connects with people. I enjoy making trips fun, relaxed, and memorable."},{"id":"gufron","url":"https://javavolcano-touroperator.com/team/gufron","name":"Gufron","role":"Guide","evidence":[{"claim":"Great Photos","quote":"Always willing to help you get your best photo.","source_author":"Adrián Martínez","source_platform":"Google Reviews"},{"claim":"Knowledgeable","quote":"He chooses good spots for photos and is full of positive energy.","source_author":"Sofiane","source_platform":"Google Reviews"}],"position":11,"knowsAbout":["Friendly & fun","Knowledgeable guide","Great logistics","Safety-first","Great photos","Always on time"],"description":"I''m someone who enjoys meaningful conversations on virtually any topic. In my professional life, I place the highest priority on safety and risk management - what some might call strict, I view as a fundamental matter of integrity and responsibility. I have a strong intuitive sense that helps me read situations quickly and accurately. Inside of work, I''m passionate about photography, where I enjoy capturing moments with attention to detail and composition. I''m also an avid music enthusiast with a diverse playlist spanning multiple genres, and I love singing along whenever the mood strikes."},{"id":"kiki","url":"https://javavolcano-touroperator.com/team/kiki","name":"Kiki","role":"Guide","evidence":[],"position":12,"knowsAbout":["Friendly & fun","Knowledgeable guide","Great logistics","Great photos","Safety-first"],"description":"\"It is He who made the earth manageable for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.\" (67:15)"},{"id":"rendi","url":"https://javavolcano-touroperator.com/team/rendi","name":"Rendi","role":"Guide","evidence":[{"claim":"Physical Support","quote":"When we went down the steep crater, he held our hands to prevent us from falling.","source_author":"Wing Shan Lui","source_platform":"Google Reviews"},{"claim":"Safety First","quote":"Kept asking about our condition... makes our journey safe.","source_author":"Michelle Jeon","source_platform":"Google Reviews"}],"position":13,"knowsAbout":["Friendly & fun","Safety-first","Great logistics","Knowledgeable guide","Great photos","Always on time"],"description":"Love meeting people from different backgrounds and making every trip feel easy and enjoyable. I like to have new friend especially from overseas because can share about our unique culture. always make sure safety during the trip and make unforgettable moment along a journey."},{"id":"taufik","url":"https://javavolcano-touroperator.com/team/taufik","name":"Taufik","role":"Guide","evidence":[],"position":14,"knowsAbout":["Friendly & fun","Knowledgeable guide","Great logistics","Safety-first","Always on time","Great photos"],"description":"Reliable and organized individual with strong communication skills. I thrive in dynamic environments and enjoy taking on new challenges. My goal is to add value through hard work and a positive, proactive attitude."}],"merged_at":"2026-04-15T17:32:49.989Z","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/team' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
