INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', '1', '{"h1":"Gufron","role":"Guide","source":"JVTO_SSOT_v4_0_CLEAN.json crew_registry","ssot_id":"gufron","evidence":[{"claim":"Great Photos","quote":"Always willing to help you get your best photo.","source_author":"Adrián Martínez","source_platform":"Google Reviews"},{"claim":"Knowledgeable","quote":"He chooses good spots for photos and is full of positive energy.","source_author":"Sofiane","source_platform":"Google Reviews"}],"merged_at":"2026-04-15T17:32:51.155Z","knowsAbout":["Friendly & fun","Knowledgeable guide","Great logistics","Safety-first","Great photos","Always on time"],"description":"I''m someone who enjoys meaningful conversations on virtually any topic. In my professional life, I place the highest priority on safety and risk management - what some might call strict, I view as a fundamental matter of integrity and responsibility. I have a strong intuitive sense that helps me read situations quickly and accurately. Inside of work, I''m passionate about photography, where I enjoy capturing moments with attention to detail and composition. I''m also an avid music enthusiast with a diverse playlist spanning multiple genres, and I love singing along whenever the mood strikes.","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/team/gufron' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
