INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 2, 'page_content', '1', '{"h1":"Joyo","role":"Driver","source":"JVTO_SSOT_v4_0_CLEAN.json crew_registry","ssot_id":"joyo","evidence":[],"merged_at":"2026-04-15T17:32:50.484Z","knowsAbout":["Friendly & fun","Safety-first","Great logistics","Knowledgeable guide"],"description":"I''m a professional driver who combines speed with precision and care. I drive fast, but always cleanly, smoothly, and safely. My vehicle is kept in impeccable condition inside and out; cleanliness and comfort are non-negotiable for every single ride. Clients frequently tell me I''m their number one choice, \"Customer Number 1\", because they know they''ll get to their destination quickly without ever feeling rushed or unsafe. I take pride in being punctual, reliable, and genuinely attentive to what each passenger needs, whether it''s a daily commute, an important business trip, airport transfer, or a special occasion.","schema_version":1}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/team/joyo' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
