INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Bromo & Ijen Private Tours for Singapore Travelers","lede":["Fly from Singapore to Bali or Surabaya, then cross East Java with a private JVTO crew. Premium logistics, a dedicated vehicle and guide, ferry crossings arranged, and written inclusions before you pay.","Licensed Indonesian tour operator · PT Java Volcano Rendezvous · NIB 1102230032918 · Trustpilot 4.8/5 (51) · Google 4.9/5 (123) · TripAdvisor 4.95/5 (21) · Founded 2015","Singapore travelers usually pair a Bali holiday with a private volcano extension — and want it organized, safe, and premium rather than a budget join-in group. JVTO runs private tours only: your own vehicle, your own driver and guide, pre-booked ferry crossings, and a written itinerary. Fly into Bali (DPS) for the easiest arrival and an overland extension, or Surabaya (SUB) for the shortest transfer to Bromo."],"sections":[{"title":"Best route from Singapore: Bali arrival or Surabaya arrival?","body":"Singapore has direct flights to both Denpasar and Surabaya. Confirm the exact airline schedule before buying non-refundable flights."},{"title":"Routes Singapore travelers usually compare","body":"All prices are official JVTO direct rates in IDR per person (based on 2 travelers). OTA retail prices may differ because of platform markup. JVTO confirms the final price in writing before payment."},{"title":"Private, all-inclusive — written before you pay","body":"Not included by default: international/domestic flights, travel insurance, visa/e-VOA fees, tips, souvenirs, personal snacks and drinks, and anything not written on the official voucher."},{"title":"What Singapore travelers say","body":"See all 195 reviews across Trustpilot, Google & TripAdvisor →"}],"faq":[{"q":"Should I start from Bali or Surabaya?","a":"Start from Bali if your easiest flight is SIN→DPS or Bali is already part of your holiday. Start from Surabaya for the shortest route to Bromo and a clean East-Java-only itinerary."},{"q":"Can I end in Surabaya and fly home the same day?","a":"Do not book a tight same-day connection after Bromo sunrise. Use a late flight only if JVTO confirms the timing is realistic, or stay one night in Surabaya."},{"q":"Can I pay in SGD?","a":"JVTO official pricing and accounting are in IDR. Cards, banks, or OTAs may display or settle in another currency, but JVTO’s direct quote is IDR-based."},{"q":"Can Singaporeans book a private Bromo and Ijen tour from Bali?","a":"Yes. JVTO runs private 3-day (3D2N) Bromo and Ijen tours that start and finish in Bali, as well as one-way Bali-to-Surabaya overland routes. Every tour is 100% private — your own air-conditioned vehicle, driver, and guide — with the Java–Bali ferry, park permits, Bromo 4WD jeep, and Ijen health-screening coordination included. No shared groups."},{"q":"Should Singapore travelers start from Bali or Surabaya?","a":"Start from Bali (DPS) if your trip already includes a Bali holiday or your easiest flight is SIN–Denpasar — the overland volcano route then extends your Bali stay. Start from Surabaya (SUB) if you want the shortest land transfer to Bromo and a clean East-Java-only loop. Singapore has direct flights to both airports."},{"q":"Is the Java–Bali ferry crossing arranged for me?","a":"Yes. On any route that crosses between Bali and Java, JVTO pre-arranges the ferry ticket and handles the vehicle crossing and driver handover, so you never queue or coordinate transfers yourself. It is written into your e-voucher before you pay."},{"q":"How do Singapore travelers pay JVTO safely?","a":"JVTO is a registered Indonesian company (PT Java Volcano Rendezvous, NIB 1102230032918) that confirms your package and IDR price in writing before any payment, then issues an official e-voucher / invoice PDF. JVTO never asks for your CVV, OTP, full card number, or banking password over chat. You can verify the company on Indonesian government registries before sending a deposit."},{"q":"Will we definitely see the Ijen Blue Fire?","a":"Not always. Blue Fire is a natural phenomenon subject to weather and gas activity, visible pre-dawn in suitable conditions only — it can never be promised in advance. JVTO plans around the viewing window and follows every BBKSDA safety decision at the crater."},{"q":"Are JVTO tours private or shared?","a":"Every JVTO tour is private. Your group has its own vehicle, driver, and guide from pickup to drop-off — you are never mixed into a join-in group. Singapore travelers who reviewed JVTO on Trustpilot specifically cited the safe, dedicated, personal service."}],"source":"scraped:https://help.javavolcano-touroperator.com/markets/singapore","scraped_at":"2026-07-28T00:00:00.000Z"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/markets/singapore' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
