INSERT INTO page_sections (page_id, sort_order, section_type, variant, content, entity_refs, asset_refs, editable) SELECT p.id, 3, 'page_content', 'live', '{"h1":"Bromo & Ijen Private Tours for Malaysia Travelers","lede":["Pakej peribadi ke Gunung Bromo, Kawah Ijen, Tumpak Sewu & Papuma — kenderaan sendiri, feri diuruskan, harga jelas, dan syarikat pelancongan yang boleh disahkan.","Fly from Malaysia to Bali or Surabaya, then let a private JVTO crew handle the whole East Java crossing — managed ferry, direct driver handovers, and one all-inclusive itinerary with no self-planning.","Licensed Indonesian tour operator · PT Java Volcano Rendezvous · NIB 1102230032918 · Trustpilot 4.8/5 (51) · Google 4.9/5 (123) · TripAdvisor 4.95/5 (21) · Founded 2015","Malaysian travelers want convenience: managed ferry crossings, direct driver handovers, and an all-inclusive package that removes cross-island planning. JVTO runs private tours only and books the Java–Bali ferry, permits, and hotels for you. AirAsia and other carriers connect Kuala Lumpur to both Denpasar (DPS) and Surabaya (SUB), so you can start in one and finish in the other without backtracking."],"sections":[{"title":"Best route from Malaysia: Bali arrival or Surabaya arrival?","body":"AirAsia flies KUL to both Denpasar and Surabaya. Confirm the exact airline schedule before buying non-refundable flights."},{"title":"Routes Malaysian travelers usually compare","body":"All prices are official JVTO direct rates in IDR per person (based on 2 travelers). OTA retail prices may differ because of platform markup. JVTO confirms the final price in writing before payment."},{"title":"Private, all-inclusive — written before you pay","body":"Not included by default: international/domestic flights, travel insurance, visa/e-VOA fees, tips, souvenirs, personal snacks and drinks, and anything not written on the official voucher."},{"title":"What Malaysian travelers say","body":"See all 195 reviews across Trustpilot, Google & TripAdvisor →"}],"faq":[{"q":"Do you manage the ferry and cross-island transfers?","a":"Yes. JVTO pre-books the Java–Bali ferry, handles the vehicle crossing, and manages the driver handover so your journey between islands is a single managed transfer written into your e-voucher."},{"q":"Is halal food available on tour?","a":"East Java is a predominantly Muslim region, and most local restaurants and hotels used on JVTO routes serve halal food. Tell JVTO your dietary requirement on WhatsApp when booking so meal stops are planned accordingly."},{"q":"Can I pay in MYR?","a":"JVTO official pricing and accounting are in IDR. Cards, banks, or OTAs may display or settle in another currency, but JVTO’s direct quote is IDR-based."},{"q":"Is there a private Bromo and Ijen tour from Bali or Surabaya for Malaysians?","a":"Yes. JVTO offers private 3-day (3D2N) Bromo and Ijen tours from both Bali and Surabaya, plus longer Ijen–Papuma–Tumpak Sewu–Bromo circuits. All tours are fully private and all-inclusive: transport, driver, guide, accommodation with breakfast, park permits, Bromo 4WD jeep, Ijen gas masks, and the Java–Bali ferry when the route crosses islands."},{"q":"Should Malaysian travelers fly to Bali (DPS) or Surabaya (SUB)?","a":"Both work — AirAsia and other carriers fly from Kuala Lumpur to both Denpasar (DPS) and Surabaya (SUB). Choose Surabaya for the shortest transfer to Bromo and Ijen; choose Bali if you want to combine the volcanoes with a Bali stay. JVTO can start in one city and finish in the other so you avoid backtracking."},{"q":"Does JVTO manage the ferry and cross-island transfers?","a":"Yes. JVTO pre-books the Java–Bali ferry, handles the vehicle crossing, and manages the driver handover directly, so Malaysian travelers get a single managed journey with no self-planning between islands. Every transfer is written into your e-voucher."},{"q":"Is halal food available on JVTO tours?","a":"East Java is a predominantly Muslim region, and most local restaurants and hotels used on JVTO routes serve halal food. Tell JVTO your dietary requirement on WhatsApp when you book so meal stops are planned accordingly."},{"q":"Will we definitely see the Ijen Blue Fire?","a":"Not always. Blue Fire is a natural phenomenon subject to weather and gas activity, visible pre-dawn in suitable conditions only — it can never be promised in advance. JVTO plans around the window and follows all BBKSDA safety rules at the crater."},{"q":"Are JVTO tours private, and is JVTO a registered operator?","a":"Every JVTO tour is private — your own vehicle, driver, and guide, never a shared group. JVTO operates as PT Java Volcano Rendezvous (NIB / TDUP 1102230032918), founded by an active Tourist Police officer, with credentials verifiable on Indonesian government registries before you pay."}],"source":"scraped:https://help.javavolcano-touroperator.com/markets/malaysia","scraped_at":"2026-07-28T00:00:00.000Z"}'::jsonb, '{}'::text[], '{}'::text[], false FROM pages p WHERE p.route = '/markets/malaysia' ON CONFLICT (page_id, sort_order) DO UPDATE SET section_type = EXCLUDED.section_type, variant = EXCLUDED.variant, content = EXCLUDED.content, entity_refs = EXCLUDED.entity_refs, asset_refs = EXCLUDED.asset_refs WHERE page_sections.editable IS NOT TRUE;
